// "Como fazer" detalhado dos exercícios da biblioteca: músculos, posição inicial, execução e erros comuns.
// Texto geral, não substitui a orientação de um profissional.
// Formato: 'Nome': [músculos, [posição inicial], [execução], [erros comuns]]
import { grupoDoExercicio } from './exercicios-base.js';

const D = {
  "Supino reto com barra": ["Peito, ombros (frente) e tríceps", ["Deite no banco com os olhos alinhados com a barra, os pés firmes no chão e as costas e o quadril apoiados.", "Segure a barra um pouco mais aberta que os ombros, com o polegar em volta da barra. Aperte as escápulas (omoplatas) uma contra a outra e mantenha o peito aberto.", "Tire a barra do suporte com os braços esticados, deixando-a sobre o meio do peito."], ["Desça a barra devagar, em 2 a 3 segundos, até tocar de leve o meio do peito. Os cotovelos ficam a cerca de 45° do corpo, nem colados nem abertos demais.", "Empurre a barra para cima, no mesmo caminho, até esticar os braços sem travar os cotovelos com força.", "Repita sem bater a barra no peito e sem tirar o quadril do banco."], ["Levantar o quadril do banco para ajudar a subir.", "Fazer a barra \"quicar\" no peito.", "Abrir os cotovelos a 90°, o que força demais o ombro.", "Fazer com carga alta sem alguém para ajudar na hora de recolocar a barra."]],
  "Supino reto com halteres": ["Peito, ombros (frente) e tríceps", ["Sente no banco com um halter apoiado em cada coxa. Deite para trás levando os halteres até a altura do peito.", "Mantenha os pés firmes no chão, as escápulas juntas e as costas apoiadas no banco.", "Estique os braços para cima, com os halteres acima do peito e as palmas voltadas para os pés."], ["Desça os halteres devagar, abrindo os cotovelos para os lados (cerca de 45° do corpo), até sentir o peito alongar. Os halteres ficam na altura do peito.", "Empurre para cima, juntando os halteres sem bater um no outro, até esticar os braços.", "Faça o movimento sempre devagar e com o mesmo caminho nos dois lados."], ["Descer demais, o que machuca o ombro.", "Deixar um lado subir mais rápido que o outro.", "Bater os halteres no alto.", "Arquear demais a lombar."]],
  "Supino inclinado com barra": ["Parte de cima do peito, ombros (frente) e tríceps", ["Ajuste o banco com inclinação leve, entre 30° e 45°. Mais que isso vira um exercício de ombro.", "Deite com as costas apoiadas, os pés firmes no chão e as escápulas juntas.", "Segure a barra um pouco mais aberta que os ombros e tire do suporte com os braços esticados."], ["Desça a barra devagar até tocar de leve a parte de cima do peito, perto da clavícula.", "Empurre a barra para cima até esticar os braços, sem travar os cotovelos com força.", "Mantenha os cotovelos levemente à frente do corpo, sem abrir demais."], ["Inclinar o banco demais.", "Levantar o quadril do banco.", "Descer a barra no pescoço ou no rosto.", "Usar carga alta sem alguém para ajudar."]],
  "Supino inclinado com halteres": ["Parte de cima do peito, ombros (frente) e tríceps", ["Ajuste o banco entre 30° e 45° e sente com os halteres apoiados nas coxas.", "Deite para trás levando os halteres até a altura do peito, com as escápulas juntas e os pés no chão.", "Estique os braços, deixando os halteres acima da parte alta do peito."], ["Desça devagar até a linha do peito, com os cotovelos um pouco abertos (cerca de 45° do corpo).", "Empurre para cima juntando os halteres sem bater, até esticar os braços.", "Mantenha os pulsos retos, alinhados com os antebraços."], ["Pulsos dobrados para trás.", "Inclinação alta demais.", "Descer rápido demais.", "Trabalhar com carga que faz um braço subir antes do outro."]],
  "Supino declinado": ["Parte de baixo do peito e tríceps", ["Deite no banco declinado e prenda bem os pés no apoio. Peça a alguém para ficar por perto, pois a barra é difícil de recolocar sozinho.", "Segure a barra um pouco mais aberta que os ombros e tire do suporte.", "Mantenha o peito aberto e as escápulas juntas."], ["Desça a barra devagar até tocar de leve a parte de baixo do peito.", "Empurre para cima até esticar os braços, sem travar os cotovelos com força.", "Respire de forma regular e não prenda o ar por muito tempo, pois a cabeça fica mais baixa que o corpo."], ["Usar carga alta sem ajuda.", "Descer a barra rápido e sem controle.", "Ficar com a cabeça muito tempo para baixo sem descansar.", "Pessoas com pressão alta ou problemas de visão devem evitar e falar com um profissional."]],
  "Supino na máquina": ["Peito, ombros (frente) e tríceps", ["Ajuste o banco para que as pegadas fiquem na altura do meio do peito.", "Sente com as costas totalmente apoiadas e os pés firmes no chão.", "Segure as pegadas com os pulsos retos."], ["Empurre para frente até quase esticar os braços, sem travar os cotovelos.", "Volte devagar, em cerca de 3 segundos, sem deixar os pesos baterem.", "Mantenha as costas e a cabeça apoiadas durante todo o movimento."], ["Ajustar o banco alto ou baixo demais e fazer a força com o ombro.", "Descolar as costas do encosto.", "Soltar o peso rápido na volta."]],
  "Supino inclinado na máquina": ["Parte de cima do peito, ombros (frente) e tríceps", ["Ajuste o banco para que as pegadas fiquem na altura da parte alta do peito.", "Sente com as costas apoiadas e os pés firmes no chão.", "Segure as pegadas com os pulsos retos."], ["Empurre para cima e à frente até quase esticar os braços.", "Volte devagar controlando o peso, até sentir o peito alongar.", "Não deixe os ombros subirem em direção às orelhas."], ["Subir os ombros.", "Arquear a lombar.", "Soltar o peso na volta."]],
  "Supino reto no smith": ["Peito, ombros (frente) e tríceps", ["Posicione o banco de modo que a barra fique sobre o meio do peito quando você estiver deitado.", "Deite com os pés firmes no chão, as escápulas juntas e as costas apoiadas.", "Segure a barra um pouco mais aberta que os ombros e gire as mãos para destravá-la."], ["Desça a barra devagar até tocar de leve o peito.", "Empurre para cima até esticar os braços, sem travar os cotovelos com força.", "Ao terminar, gire as mãos para travar a barra de volta no suporte."], ["Banco mal posicionado, deixando a barra no pescoço ou no abdômen.", "Levantar o quadril.", "Esquecer de travar a barra no fim da série."]],
  "Supino inclinado no smith": ["Parte de cima do peito, ombros (frente) e tríceps", ["Posicione o banco inclinado (30° a 45°) de modo que a barra desça na parte alta do peito.", "Deite com os pés firmes e as escápulas juntas.", "Segure a barra um pouco mais aberta que os ombros e destrave."], ["Desça devagar até tocar de leve a parte alta do peito.", "Empurre para cima sem arquear a lombar, até esticar os braços.", "Trave a barra no suporte quando terminar a série."], ["Banco mal posicionado.", "Arquear demais a lombar.", "Descer rápido demais."]],
  "Crucifixo reto": ["Peito (principalmente a parte do meio) e ombros (frente)", ["Deite no banco reto com um halter em cada mão, os braços esticados acima do peito e as palmas viradas uma para a outra.", "Dobre levemente os cotovelos e mantenha essa dobra durante todo o exercício.", "Mantenha os pés firmes no chão e as costas apoiadas."], ["Abra os braços para os lados em um arco largo, devagar, até sentir o peito alongar. Os halteres descem até a altura do peito, não mais que isso.", "Feche os braços em arco, como se abraçasse uma árvore grande, até os halteres quase se encontrarem acima do peito.", "Faça o movimento sempre com os cotovelos na mesma dobra, sem esticar nem dobrar mais."], ["Transformar em supino, dobrando e esticando os cotovelos.", "Descer muito, forçando o ombro.", "Usar carga alta demais, perdendo o controle."]],
  "Crucifixo inclinado": ["Parte de cima do peito e ombros (frente)", ["Ajuste o banco com inclinação leve (30° a 45°) e deite com um halter em cada mão, os braços esticados acima do peito.", "Dobre levemente os cotovelos e mantenha essa dobra.", "Mantenha as costas apoiadas e os pés firmes."], ["Abra os braços em arco, devagar, até sentir a parte de cima do peito alongar.", "Feche em arco até os halteres quase se encontrarem acima do peito.", "Use uma carga que permita controlar o movimento todo."], ["Dobrar e esticar os cotovelos (vira supino).", "Descer demais.", "Carga alta que faz o ombro assumir o trabalho."]],
  "Crucifixo na máquina": ["Peito e ombros (frente)", ["É o mesmo movimento do peck deck. Ajuste o banco para que as pegadas fiquem na altura do peito.", "Sente com as costas totalmente apoiadas, os pés firmes e os cotovelos levemente dobrados.", "Apoie os antebraços nas almofadas ou segure as pegadas, conforme a máquina."], ["Junte os braços à frente do peito, apertando o peito no final, sem bater os pesos.", "Volte devagar, abrindo até sentir o peito alongar, sem forçar o ombro para trás.", "Respire de forma regular, soltando o ar ao fechar."], ["Ajustar o banco alto demais.", "Abrir demais e forçar o ombro.", "Soltar o peso na volta."]],
  "Peck deck": ["Peito e ombros (frente)", ["Também chamado de crucifixo na máquina. Ajuste o banco para que as pegadas fiquem na altura do peito.", "Sente com as costas totalmente apoiadas e os pés firmes.", "Mantenha os cotovelos levemente dobrados."], ["Junte os braços à frente, apertando o peito no final, sem bater os pesos.", "Volte devagar, abrindo até sentir o peito alongar, sem forçar o ombro.", "Respire soltando o ar ao fechar."], ["Banco alto demais.", "Abrir demais.", "Soltar o peso na volta."]],
  "Crossover na polia": ["Peito e ombros (frente)", ["Fique em pé entre as duas polias, com os cabos na altura dos ombros ou um pouco acima. Segure uma alça em cada mão.", "Dê um passo à frente, com um pé na frente do outro, e incline o tronco levemente à frente, mantendo as costas retas.", "Mantenha os cotovelos levemente dobrados."], ["Leve as mãos à frente em arco, juntando-as na altura do peito ou do abdômen, e aperte o peito.", "Volte devagar, abrindo os braços até sentir o peito alongar, sem passar da linha dos ombros.", "Mantenha o tronco parado, sem balançar."], ["Usar o impulso do corpo.", "Dobrar e esticar os cotovelos.", "Carga alta que faz o tronco balançar."]],
  "Crossover polia baixa": ["Parte de cima do peito e ombros (frente)", ["Ajuste as polias na parte de baixo. Segure uma alça em cada mão e dê um passo à frente.", "Incline o tronco levemente à frente, com as costas retas.", "Mantenha os cotovelos levemente dobrados."], ["Leve as mãos para cima e à frente em arco, até a altura do queixo, juntando-as na frente do peito.", "Volte devagar até as mãos ficarem na altura do quadril, alongando o peito.", "Não use o impulso do corpo."], ["Balançar o tronco.", "Subir os ombros.", "Dobrar e esticar os cotovelos."]],
  "Crossover polia alta": ["Parte de baixo do peito e ombros (frente)", ["Ajuste as polias no alto. Segure uma alça em cada mão e dê um passo à frente.", "Incline o tronco levemente à frente, com as costas retas.", "Mantenha os cotovelos levemente dobrados."], ["Leve as mãos para baixo e à frente, juntando-as na altura do quadril, apertando o peito.", "Volte devagar, abrindo os braços até a altura dos ombros.", "Mantenha o tronco parado."], ["Puxar com o ombro em vez do peito.", "Usar o impulso do corpo.", "Esticar os cotovelos."]],
  "Pullover com halter": ["Peito, costas (dorsais) e tríceps", ["Deite transversalmente no banco, com só os ombros e a parte de cima das costas apoiados. Os pés ficam firmes no chão e o quadril um pouco abaixo do banco.", "Segure um halter com as duas mãos, na vertical, acima do peito, com os braços quase esticados.", "Mantenha os cotovelos levemente dobrados."], ["Leve o halter para trás da cabeça em um arco, devagar, até sentir o peito e as costas alongarem. Não force além do conforto.", "Traga o halter de volta ao ponto de partida, puxando com o peito e as costas.", "Respire fundo ao descer e solte o ar ao subir."], ["Descer demais e forçar o ombro.", "Dobrar muito os cotovelos.", "Arquear demais a lombar.", "Carga alta demais."]],
  "Flexão de braço": ["Peito, ombros (frente) e tríceps", ["Apoie as mãos no chão um pouco mais abertas que os ombros e os pés juntos ou levemente afastados.", "Mantenha o corpo reto, da cabeça aos calcanhares, como uma prancha, com o abdômen e o glúteo contraídos.", "Se for difícil, apoie os joelhos no chão (mantendo o corpo reto dos joelhos à cabeça)."], ["Desça dobrando os cotovelos, a cerca de 45° do corpo, até o peito chegar perto do chão.", "Empurre o chão e volte até esticar os braços.", "Mantenha o pescoço neutro, olhando um pouco à frente."], ["Deixar o quadril cair ou subir demais.", "Abrir os cotovelos em 90°.", "Não descer o suficiente."]],
  "Flexão com pés elevados": ["Parte de cima do peito, ombros (frente) e tríceps", ["Apoie os pés em um banco ou step, as mãos no chão um pouco mais abertas que os ombros.", "Mantenha o corpo reto, com o abdômen e o glúteo contraídos.", "Quanto mais alto o apoio dos pés, mais difícil."], ["Desça dobrando os cotovelos até o peito chegar perto do chão.", "Empurre o chão e volte até esticar os braços.", "Mantenha o corpo reto, sem deixar o quadril cair."], ["Quadril caindo.", "Apoio alto demais para o seu nível.", "Cabeça caída para frente."]],
  "Mergulho nas paralelas": ["Peito (parte de baixo), tríceps e ombros (frente)", ["Apoie-se nas barras paralelas com os braços esticados e o corpo suspenso, sem encostar os pés no chão.", "Incline o tronco levemente à frente para focar no peito. Mais reto foca mais no tríceps.", "Cruze os pés ou deixe as pernas dobradas atrás."], ["Desça dobrando os cotovelos até um ângulo confortável (cerca de 90°), sem forçar o ombro.", "Empurre as barras e suba até esticar os braços, sem travar os cotovelos com força.", "Faça o movimento devagar e sem balançar o corpo."], ["Descer demais e forçar o ombro.", "Balançar as pernas.", "Fazer com ombros dolorosos.", "Para iniciantes, existe máquina assistida."]],
  "Puxada frontal": ["Costas (dorsais), bíceps e antebraço", ["Sente na máquina e ajuste o apoio das coxas para que fiquem presas. Segure a barra com as mãos mais abertas que os ombros, com as palmas para frente.", "Mantenha o peito aberto, as costas retas e o tronco levemente inclinado para trás.", "Comece com os braços esticados."], ["Puxe a barra até a altura do queixo, levando os cotovelos para baixo e para trás, e junte as escápulas.", "Volte devagar, esticando os braços até sentir as costas alongarem.", "Mantenha o tronco parado, sem balançar para ajudar."], ["Balançar o tronco para ajudar.", "Puxar atrás da nuca.", "Encolher os ombros.", "Soltar a barra rápido na volta."]],
  "Puxada atrás da nuca": ["Costas (dorsais e parte de cima), ombros (parte de trás) e bíceps", ["Exige boa mobilidade de ombro. Sente na máquina com as coxas presas.", "Segure a barra bem aberta, com as palmas para frente. Incline levemente a cabeça para frente, sem forçar o pescoço.", "Comece com os braços esticados."], ["Puxe a barra até a altura da nuca, mantendo o tronco reto, e junte as escápulas.", "Volte devagar até os braços esticarem.", "Se sentir desconforto no ombro ou no pescoço, pare e prefira a puxada frontal."], ["Puxar com muita carga e forçar o ombro.", "Jogar a cabeça à frente.", "Quem tem limitação no ombro deve evitar."]],
  "Puxada com triângulo": ["Costas (parte do meio e dorsais) e bíceps", ["Sente na máquina com as coxas presas e segure o triângulo com as palmas voltadas uma para a outra.", "Mantenha o peito aberto e o tronco levemente inclinado para trás.", "Comece com os braços esticados."], ["Puxe o triângulo até o peito, levando os cotovelos junto ao corpo.", "Aperte as costas por um instante e volte devagar até alongar.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Soltar o peso na volta.", "Puxar com os braços e não com as costas."]],
  "Puxada com pegada supinada": ["Costas (dorsais) e bíceps", ["Sente na máquina e segure a barra com as palmas voltadas para você, na largura dos ombros.", "Mantenha o peito aberto e o tronco levemente inclinado para trás.", "Comece com os braços esticados."], ["Puxe a barra até o peito, levando os cotovelos para baixo e para trás.", "Volte devagar até os braços esticarem.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Encolher os ombros.", "Esta pegada trabalha mais o bíceps, então a carga pode precisar ser menor."]],
  "Puxada articulada": ["Costas (dorsais) e bíceps", ["Sente na máquina e ajuste o apoio das coxas. Segure as alças com as palmas voltadas uma para a outra ou para frente, conforme o aparelho.", "Mantenha o peito aberto e as costas retas.", "Comece com os braços esticados."], ["Puxe as alças para baixo levando os cotovelos junto ao corpo, juntando as escápulas.", "Suba devagar até alongar bem as costas.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Encolher os ombros.", "Soltar o peso na volta."]],
  "Puxada unilateral na polia": ["Costas (dorsais) e bíceps", ["Sente na máquina, prenda as coxas e segure a alça com uma mão. A outra mão pode segurar o apoio.", "Mantenha o peito aberto e as costas retas.", "Comece com o braço esticado."], ["Puxe a alça em direção ao ombro, levando o cotovelo para baixo e para trás, até sentir as costas contraírem.", "Volte devagar até esticar o braço.", "Faça todas as repetições de um lado e depois troque."], ["Girar o tronco para ajudar.", "Encolher o ombro.", "Usar carga alta e perder o controle."]],
  "Barra fixa": ["Costas (dorsais), bíceps e antebraço", ["Segure a barra um pouco mais aberta que os ombros, com as palmas voltadas para frente, e fique pendurado com os braços esticados.", "Cruze os pés atrás ou deixe as pernas retas. Contraia o abdômen.", "Mantenha o peito aberto."], ["Puxe o corpo para cima levando os cotovelos para baixo e para trás, até o queixo passar da barra.", "Desça devagar, em cerca de 3 segundos, até esticar os braços.", "Evite balançar o corpo para ganhar impulso."], ["Balançar o corpo.", "Não esticar os braços totalmente na descida.", "Encolher os ombros.", "Para iniciantes, existe a máquina assistida."]],
  "Barra fixa supinada": ["Costas (dorsais) e bíceps", ["Segure a barra com as palmas voltadas para você, na largura dos ombros, e fique pendurado com os braços esticados.", "Contraia o abdômen e mantenha o peito aberto.", "Cruze os pés atrás ou deixe as pernas retas."], ["Puxe o corpo até o queixo passar da barra, levando os cotovelos para baixo.", "Desça devagar até esticar os braços.", "Evite balançar."], ["Balançar o corpo.", "Não descer até esticar os braços.", "Esta pegada exige mais do bíceps."]],
  "Barra fixa assistida": ["Costas (dorsais), bíceps e antebraço", ["Na máquina assistida, ajuste o peso que ajuda na subida. Quanto maior o peso ajustado, mais fácil.", "Apoie os joelhos ou os pés na plataforma e segure a barra com a pegada desejada.", "Mantenha o peito aberto e o abdômen contraído."], ["Puxe o corpo para cima até o queixo passar da barra, levando os cotovelos para baixo.", "Desça devagar até esticar os braços.", "Diminua a ajuda aos poucos, conforme ganhar força."], ["Usar sempre o mesmo peso de ajuda e não progredir.", "Balançar o corpo."]],
  "Remada curvada com barra": ["Costas (parte do meio e dorsais), bíceps e lombar", ["Em pé, segure a barra um pouco mais aberta que os ombros, com as palmas voltadas para você ou para baixo.", "Incline o tronco à frente com o quadril para trás e os joelhos levemente dobrados, mantendo as costas retas (cerca de 45°).", "Deixe a barra pendurada à frente das pernas, com os braços esticados."], ["Puxe a barra em direção ao umbigo, levando os cotovelos para trás e juntando as escápulas.", "Desça devagar, em cerca de 3 segundos, até esticar os braços.", "Mantenha as costas retas e o tronco parado durante todo o movimento."], ["Curvar as costas (risco para a lombar).", "Usar o impulso do corpo.", "Puxar para o peito em vez do umbigo.", "Carga alta demais."]],
  "Remada curvada com halteres": ["Costas (parte do meio e dorsais) e bíceps", ["Em pé com os pés na largura dos ombros, segure um halter em cada mão.", "Incline o tronco à frente com o quadril para trás e os joelhos levemente dobrados, com as costas retas.", "Deixe os halteres pendurados à frente, com as palmas voltadas uma para a outra."], ["Puxe os halteres até a lateral do abdômen, levando os cotovelos para trás e junto ao corpo.", "Desça devagar até esticar os braços.", "Mantenha o tronco parado e a coluna reta."], ["Curvar as costas.", "Usar o impulso do corpo.", "Subir o tronco ao puxar."]],
  "Remada baixa": ["Costas (parte do meio e dorsais) e bíceps", ["Sente na máquina com os pés apoiados e os joelhos levemente dobrados. Segure o triângulo ou a barra.", "Mantenha as costas retas, o peito aberto e o tronco em pé, levemente inclinado à frente no início.", "Comece com os braços esticados."], ["Puxe o cabo até o abdômen, levando os cotovelos para trás e juntando as escápulas.", "Volte devagar até esticar os braços, sem curvar o tronco.", "Mantenha o tronco parado, sem balançar para frente e para trás."], ["Balançar o tronco.", "Curvar as costas ao esticar os braços.", "Encolher os ombros."]],
  "Remada baixa unilateral": ["Costas (parte do meio e dorsais) e bíceps", ["Sente na máquina com os pés apoiados e os joelhos levemente dobrados. Segure uma alça com uma mão.", "Mantenha as costas retas e o peito aberto.", "Comece com o braço esticado."], ["Puxe a alça até a lateral do abdômen, com o cotovelo junto ao corpo.", "Volte devagar até esticar o braço, sem girar o tronco.", "Faça todas as repetições de um lado e depois troque."], ["Girar o tronco.", "Encolher o ombro.", "Balançar o corpo."]],
  "Remada articulada": ["Costas (parte do meio e dorsais) e bíceps", ["Sente na máquina com o peito apoiado no suporte e os pés firmes no chão.", "Segure as alças com os braços esticados à frente.", "Mantenha as costas retas e o peito aberto."], ["Puxe as alças levando os cotovelos para trás, juntando as escápulas.", "Volte devagar até alongar as costas.", "Mantenha o peito sempre apoiado."], ["Descolar o peito do apoio.", "Encolher os ombros.", "Soltar o peso na volta."]],
  "Remada cavalinho": ["Costas (parte do meio e dorsais) e bíceps", ["Fique em pé sobre a plataforma, com o peito apoiado no suporte (se houver) ou o tronco inclinado com as costas retas.", "Segure as alças ou a barra com os braços esticados.", "Mantenha os joelhos levemente dobrados."], ["Puxe a barra em direção ao peito ou abdômen, levando os cotovelos para trás e juntando as escápulas.", "Desça devagar até esticar os braços.", "Mantenha as costas retas durante todo o movimento."], ["Curvar as costas.", "Usar o impulso do corpo.", "Carga alta que faz o tronco subir."]],
  "Remada com barra T": ["Costas (parte do meio e dorsais) e bíceps", ["Fique em pé sobre a plataforma, com a barra entre as pernas. Incline o tronco à frente com as costas retas e os joelhos levemente dobrados.", "Segure a barra ou as alças com os braços esticados.", "Mantenha o peito aberto."], ["Puxe a barra em direção ao peito, juntando as escápulas.", "Desça devagar até esticar os braços.", "Mantenha as costas retas e o tronco parado."], ["Curvar as costas.", "Usar o impulso do corpo.", "Subir o tronco ao puxar."]],
  "Remada Pendlay": ["Costas (parte do meio e dorsais), lombar e bíceps", ["Fique em pé com os pés na largura dos ombros e a barra no chão, sobre os pés.", "Incline o tronco até ficar quase paralelo ao chão, com as costas retas e os joelhos levemente dobrados.", "Segure a barra um pouco mais aberta que os ombros."], ["Puxe a barra de forma explosiva até o abdômen, juntando as escápulas.", "Desça a barra até o chão, parando por um instante em cada repetição.", "Mantenha as costas retas durante todo o movimento. É um exercício avançado."], ["Curvar as costas.", "Subir o tronco ao puxar.", "Carga alta demais.", "Peça orientação de um profissional antes de colocar carga."]],
  "Remada no smith": ["Costas (parte do meio e dorsais) e bíceps", ["Fique em pé com os pés na largura dos ombros e a barra do smith à frente. Segure a barra com as palmas para baixo.", "Incline o tronco à frente com as costas retas e os joelhos levemente dobrados.", "Comece com os braços esticados."], ["Puxe a barra em direção ao abdômen, levando os cotovelos para trás.", "Desça devagar até esticar os braços.", "Mantenha as costas retas."], ["Curvar as costas.", "Subir o tronco.", "Usar o impulso do corpo."]],
  "Remada unilateral com halter": ["Costas (dorsais e parte do meio) e bíceps", ["Apoie uma mão e o joelho do mesmo lado em um banco, com as costas retas e paralelas ao chão. O outro pé fica firme no chão.", "Segure um halter com a mão livre, com o braço esticado e a palma voltada para o corpo.", "Mantenha o pescoço alinhado com a coluna."], ["Puxe o halter até a cintura, levando o cotovelo para trás e junto ao corpo.", "Desça devagar até esticar o braço.", "Faça todas as repetições de um lado e depois troque."], ["Girar o tronco.", "Puxar com o ombro e não com as costas.", "Usar o impulso do corpo."]],
  "Pulldown com corda": ["Costas (dorsais) e tríceps", ["Em pé, de frente para a polia alta, segure a corda com os braços quase esticados.", "Incline o tronco levemente à frente, com as costas retas e o abdômen contraído.", "Mantenha os pés firmes."], ["Puxe a corda para baixo, em arco, até a altura das coxas, mantendo os braços quase esticados.", "Volte devagar, sentindo as costas alongarem.", "Mantenha o tronco parado."], ["Dobrar demais os cotovelos (vira tríceps).", "Balançar o tronco.", "Soltar o peso na volta."]],
  "Pullover na polia": ["Costas (dorsais) e tríceps", ["Em pé, de frente para a polia alta, segure a barra reta ou a corda com os braços quase esticados.", "Incline o tronco levemente à frente, com as costas retas.", "Mantenha os cotovelos levemente dobrados."], ["Puxe a barra para baixo, em arco, até as coxas, mantendo os braços quase retos.", "Volte devagar, sentindo as costas alongarem.", "Mantenha o tronco parado."], ["Dobrar os cotovelos.", "Balançar o tronco.", "Soltar o peso na volta."]],
  "Hiperextensão lombar": ["Lombar, glúteos e parte de trás das coxas", ["No banco de hiperextensão, apoie o quadril na almofada e prenda os pés. O corpo fica em linha reta, da cabeça aos pés, ou com o tronco levemente curvado à frente.", "Cruze os braços no peito ou coloque as mãos atrás da cabeça. Para mais dificuldade, segure um peso no peito.", "Mantenha o pescoço alinhado com a coluna."], ["Desça o tronco devagar com as costas retas, até uns 45° ou até sentir a parte de trás das coxas alongar.", "Suba contraindo glúteos e lombar até o corpo ficar alinhado com as pernas.", "Não passe da linha reta para trás, para não forçar a lombar."], ["Subir demais e arquear a lombar.", "Usar o impulso.", "Descer rápido."]],
  "Levantamento terra": ["Costas (lombar e parte do meio), glúteos, parte de trás das coxas e antebraço", ["Fique em pé com os pés na largura do quadril e a barra sobre o meio dos pés, perto das canelas.", "Dobre o quadril e os joelhos e segure a barra um pouco mais aberta que as pernas. Mantenha as costas retas, o peito aberto e os braços esticados.", "Olhe um pouco à frente, mantendo o pescoço alinhado com a coluna."], ["Empurre o chão com os pés e estenda quadril e joelhos juntos, mantendo a barra rente às pernas.", "Suba até ficar em pé, com o quadril e os joelhos esticados, sem se inclinar para trás.", "Desça a barra devagar, levando o quadril para trás e dobrando os joelhos, mantendo as costas retas."], ["Curvar as costas (risco para a lombar).", "Afastar a barra do corpo.", "Levantar o quadril antes dos ombros.", "Peça orientação de um profissional antes de colocar carga."]],
  "Desenvolvimento com barra": ["Ombros (frente e lateral), tríceps e parte de cima do peito", ["Sente em um banco com encosto (ou fique em pé) e segure a barra um pouco mais aberta que os ombros.", "Tire a barra do suporte e leve-a à altura do queixo ou da clavícula, com os cotovelos um pouco à frente do corpo.", "Mantenha o abdômen contraído e as costas apoiadas."], ["Empurre a barra para cima até esticar os braços, passando a cabeça levemente para frente no final, sem travar os cotovelos com força.", "Desça devagar até a altura do queixo, em cerca de 3 segundos.", "Mantenha a lombar sem arquear durante todo o movimento."], ["Arquear a lombar para ajudar a subir.", "Descer a barra atrás da cabeça.", "Usar o impulso das pernas (se estiver em pé).", "Carga alta sem ajuda para recolocar a barra."]],
  "Desenvolvimento com halteres": ["Ombros (frente e lateral) e tríceps", ["Sente em um banco com encosto, com um halter em cada mão apoiado nas coxas. Leve os halteres para os ombros, um de cada vez.", "Segure os halteres na altura das orelhas, com as palmas voltadas para frente e os cotovelos abertos para os lados e um pouco à frente.", "Mantenha as costas apoiadas e o abdômen contraído."], ["Empurre os halteres para cima, aproximando-os sem bater, até esticar os braços.", "Desça devagar até a altura das orelhas, em cerca de 3 segundos.", "Mantenha os pulsos retos."], ["Arquear a lombar.", "Bater os halteres no alto.", "Deixar um braço subir mais rápido que o outro.", "Descer demais."]],
  "Desenvolvimento Arnold": ["Ombros (todas as partes) e tríceps", ["Sente em um banco com encosto, com um halter em cada mão, na altura do peito, com as palmas voltadas para você e os cotovelos à frente.", "Mantenha as costas apoiadas e o abdômen contraído.", "Use carga leve, pois o movimento exige mais controle."], ["Empurre os halteres para cima, girando as palmas para frente durante a subida, até esticar os braços.", "Desça devagar, girando as palmas de volta para você, até a altura do peito.", "Faça o giro de forma contínua e suave."], ["Arquear a lombar.", "Girar rápido demais.", "Usar carga alta e perder o controle."]],
  "Desenvolvimento na máquina": ["Ombros (frente e lateral) e tríceps", ["Ajuste o banco para que as pegadas fiquem na altura dos ombros.", "Sente com as costas apoiadas e os pés firmes no chão.", "Segure as pegadas com os pulsos retos."], ["Empurre para cima até quase esticar os braços, sem travar os cotovelos.", "Desça devagar até a altura dos ombros.", "Mantenha as costas apoiadas."], ["Arquear a lombar.", "Soltar o peso na descida.", "Banco mal ajustado, forçando o ombro."]],
  "Desenvolvimento no smith": ["Ombros (frente e lateral) e tríceps", ["Posicione um banco com encosto sob a barra, com a barra na altura do queixo quando você estiver sentado.", "Segure a barra um pouco mais aberta que os ombros e gire as mãos para destravar.", "Mantenha as costas apoiadas e o abdômen contraído."], ["Empurre a barra para cima até esticar os braços, sem travar os cotovelos com força.", "Desça devagar até a altura do queixo.", "Trave a barra no suporte ao terminar."], ["Arquear a lombar.", "Descer a barra atrás da cabeça.", "Esquecer de travar a barra no fim."]],
  "Elevação lateral": ["Ombros (lateral)", ["Em pé, com os pés na largura dos ombros, segure um halter em cada mão ao lado do corpo, com as palmas voltadas para as coxas.", "Mantenha uma leve dobra nos cotovelos e o abdômen contraído.", "Incline o tronco levemente à frente, se preferir."], ["Levante os braços para os lados até a altura dos ombros, como se despejasse água de uma jarra (o cotovelo sobe um pouco antes da mão).", "Segure um instante no alto e desça devagar, em cerca de 3 segundos.", "Mantenha o pescoço relaxado, sem subir os ombros."], ["Usar o impulso do corpo.", "Subir demais, acima da linha dos ombros.", "Encolher os ombros.", "Usar carga alta demais. Use carga leve."]],
  "Elevação lateral na polia": ["Ombros (lateral)", ["Em pé, de lado para a polia baixa, segure o cabo com a mão de fora (a mais distante da polia), com o braço cruzando à frente do corpo.", "Mantenha uma leve dobra no cotovelo e o abdômen contraído.", "Apoie a outra mão para se equilibrar, se quiser."], ["Levante o braço para o lado, em arco, até a altura do ombro.", "Desça devagar, em cerca de 3 segundos.", "Faça todas as repetições de um lado e depois troque."], ["Usar o impulso do corpo.", "Subir demais.", "Encolher o ombro."]],
  "Elevação lateral na máquina": ["Ombros (lateral)", ["Ajuste o banco para que os ombros fiquem alinhados com o eixo da máquina.", "Sente com as costas apoiadas e apoie os antebraços nas almofadas.", "Mantenha os pés firmes no chão."], ["Levante os cotovelos para os lados até a altura dos ombros.", "Desça devagar sem deixar o peso bater.", "Mantenha o pescoço relaxado."], ["Encolher os ombros.", "Subir demais.", "Soltar o peso na descida."]],
  "Elevação frontal": ["Ombros (frente) e parte de cima do peito", ["Em pé, com os pés na largura dos ombros, segure um halter em cada mão à frente das coxas, com as palmas voltadas para elas.", "Mantenha uma leve dobra nos cotovelos e o abdômen contraído.", "Mantenha as costas retas."], ["Levante um braço à frente até a altura dos olhos (ou do ombro), devagar.", "Desça devagar, em cerca de 3 segundos, e faça o outro braço (ou os dois ao mesmo tempo).", "Mantenha o tronco parado."], ["Balançar o tronco para ajudar.", "Subir demais.", "Usar carga alta demais."]],
  "Elevação frontal com anilha": ["Ombros (frente) e parte de cima do peito", ["Em pé, segure uma anilha com as duas mãos, na posição de 3 e 9 horas, à frente das coxas.", "Mantenha uma leve dobra nos cotovelos e o abdômen contraído.", "Mantenha as costas retas."], ["Levante a anilha à frente até a altura dos olhos, devagar.", "Desça devagar, em cerca de 3 segundos.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Subir demais.", "Arquear a lombar."]],
  "Elevação frontal na polia": ["Ombros (frente)", ["De costas para a polia baixa, segure o cabo com uma mão (ou uma barra reta com as duas), com o braço esticado ao lado do corpo.", "Dê um passo à frente para dar espaço, com o abdômen contraído.", "Mantenha uma leve dobra no cotovelo."], ["Levante o braço à frente até a altura do ombro.", "Desça devagar, controlando o peso.", "Faça todas as repetições de um lado e depois troque."], ["Balançar o tronco.", "Subir demais.", "Soltar o peso na descida."]],
  "Crucifixo invertido": ["Ombros (parte de trás) e costas (parte de cima)", ["Sente na ponta de um banco, incline o tronco à frente até quase encostar o peito nas coxas, com as costas retas. Ou deite de bruços em um banco inclinado.", "Segure um halter em cada mão, com os braços pendurados e as palmas voltadas uma para a outra.", "Dobre levemente os cotovelos."], ["Abra os braços para os lados, em arco, até a altura dos ombros, juntando as escápulas.", "Desça devagar, em cerca de 3 segundos.", "Use carga leve e mantenha o tronco parado."], ["Usar o impulso do corpo.", "Subir o tronco.", "Usar carga alta demais."]],
  "Crucifixo invertido na máquina": ["Ombros (parte de trás) e costas (parte de cima)", ["Sente de frente para o apoio do peito, com o peito apoiado e os pés firmes. Ajuste a altura para que as pegadas fiquem na altura dos ombros.", "Segure as alças com os braços esticados à frente.", "Mantenha as costas retas."], ["Abra os braços para trás, em arco, até a altura dos ombros, juntando as escápulas.", "Volte devagar, sem deixar o peso bater.", "Mantenha o peito apoiado."], ["Descolar o peito do apoio.", "Encolher os ombros.", "Soltar o peso na volta."]],
  "Crucifixo invertido na polia": ["Ombros (parte de trás) e costas (parte de cima)", ["Fique em pé entre as polias, com os cabos na altura dos ombros. Segure o cabo da esquerda com a mão direita e o da direita com a esquerda (cabos cruzados).", "Incline levemente o tronco à frente e dobre levemente os cotovelos.", "Mantenha o abdômen contraído."], ["Abra os braços para os lados e para trás, em arco, até a altura dos ombros, juntando as escápulas.", "Volte devagar, cruzando os braços à frente.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Dobrar e esticar os cotovelos.", "Subir demais."]],
  "Face pull": ["Ombros (parte de trás), parte de cima das costas e manguito rotador", ["Ajuste a polia na altura do rosto e prenda a corda. Segure as pontas da corda com as palmas voltadas uma para a outra e dê alguns passos para trás.", "Mantenha o tronco reto, os pés firmes e os braços esticados à frente.", "Use carga leve."], ["Puxe a corda em direção ao rosto, abrindo os cotovelos para os lados e para cima, e junte as escápulas. As mãos terminam ao lado das orelhas.", "Segure um instante e volte devagar até esticar os braços.", "Mantenha o tronco parado."], ["Usar carga alta e balançar o corpo.", "Puxar baixo, na altura do peito.", "Subir os ombros."]],
  "Remada alta": ["Ombros (lateral e frente), trapézio e bíceps", ["Em pé, segure a barra (ou halteres) à frente das coxas, com as mãos um pouco mais próximas que os ombros e as palmas voltadas para você.", "Mantenha o abdômen contraído e as costas retas.", "Comece com os braços esticados."], ["Suba a barra rente ao corpo, levando os cotovelos para cima e para os lados, até a altura do peito (ou dos ombros). Os cotovelos ficam mais altos que as mãos.", "Desça devagar, em cerca de 3 segundos.", "Não suba acima da altura do peito se sentir desconforto no ombro."], ["Subir demais e forçar o ombro.", "Usar o impulso do corpo.", "Pessoas com dor no ombro devem evitar e falar com um profissional."]],
  "Encolhimento de ombros": ["Trapézio (parte de cima)", ["Em pé, com os pés na largura dos ombros, segure um halter em cada mão (ou uma barra) ao lado do corpo, com os braços esticados.", "Mantenha as costas retas e o pescoço neutro.", "Olhe para frente."], ["Suba os ombros em direção às orelhas, o máximo que conseguir, sem dobrar os cotovelos.", "Segure um instante no alto e desça devagar.", "Não gire os ombros para frente ou para trás."], ["Girar os ombros.", "Dobrar os cotovelos.", "Usar carga alta demais e fazer movimentos curtos."]],
  "Encolhimento com halteres": ["Trapézio (parte de cima)", ["Em pé, com os pés na largura dos ombros, segure um halter em cada mão ao lado do corpo, com os braços esticados.", "Mantenha as costas retas e o pescoço neutro.", "Olhe para frente."], ["Suba os ombros em direção às orelhas, o máximo que conseguir, sem dobrar os cotovelos.", "Segure um instante e desça devagar.", "Não gire os ombros."], ["Girar os ombros.", "Dobrar os cotovelos.", "Movimento curto demais."]],
  "Encolhimento com barra": ["Trapézio (parte de cima)", ["Em pé, segure a barra à frente das coxas, um pouco mais aberta que os ombros, com os braços esticados.", "Mantenha as costas retas e o pescoço neutro.", "Olhe para frente."], ["Suba os ombros em direção às orelhas, o máximo que conseguir, sem dobrar os cotovelos.", "Segure um instante e desça devagar.", "Não gire os ombros."], ["Girar os ombros.", "Dobrar os cotovelos.", "Usar carga alta e fazer movimentos curtos."]],
  "Encolhimento no smith": ["Trapézio (parte de cima)", ["Em pé, à frente da barra do smith, segure a barra na altura das coxas com os braços esticados.", "Mantenha as costas retas e o pescoço neutro.", "Olhe para frente."], ["Suba os ombros em direção às orelhas, o máximo que conseguir, sem dobrar os cotovelos.", "Segure um instante e desça devagar.", "Não gire os ombros."], ["Girar os ombros.", "Dobrar os cotovelos.", "Movimento curto demais."]],
  "Encolhimento na máquina": ["Trapézio (parte de cima)", ["Ajuste a máquina e segure as alças com os braços esticados ao lado do corpo.", "Mantenha as costas retas e o pescoço neutro.", "Olhe para frente."], ["Suba os ombros em direção às orelhas, o máximo que conseguir.", "Segure um instante e desça devagar.", "Não dobre os cotovelos."], ["Dobrar os cotovelos.", "Girar os ombros.", "Soltar o peso na descida."]],
  "Rosca direta com barra": ["Bíceps e antebraço", ["Em pé, com os pés na largura dos ombros, segure a barra com as palmas voltadas para cima, na largura dos ombros.", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído.", "Comece com os braços esticados à frente das coxas."], ["Dobre os cotovelos levando a barra até os ombros, sem mover os cotovelos para frente.", "Aperte o bíceps no alto e desça devagar, em cerca de 3 segundos, até esticar os braços.", "Mantenha o tronco parado."], ["Balançar o tronco para ajudar.", "Levar os cotovelos à frente.", "Não esticar os braços na descida.", "Carga alta demais."]],
  "Rosca direta com barra W": ["Bíceps e antebraço", ["Em pé, segure a barra W com as palmas voltadas para cima (ou levemente inclinadas), nas curvas. A barra W alivia os punhos.", "Mantenha os cotovelos junto ao corpo e as costas retas.", "Comece com os braços esticados."], ["Dobre os cotovelos levando a barra até os ombros, sem mover os cotovelos para frente.", "Aperte o bíceps e desça devagar até esticar os braços.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Levar os cotovelos à frente.", "Carga alta demais."]],
  "Rosca direta com halteres": ["Bíceps e antebraço", ["Em pé, segure um halter em cada mão ao lado do corpo, com as palmas voltadas para a frente.", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído.", "Comece com os braços esticados."], ["Dobre os cotovelos levando os halteres até os ombros, sem mover os cotovelos para frente.", "Aperte o bíceps e desça devagar até esticar os braços.", "Faça os dois braços juntos."], ["Balançar o tronco.", "Levar os cotovelos à frente.", "Carga alta demais."]],
  "Rosca alternada": ["Bíceps e antebraço", ["Em pé, segure um halter em cada mão ao lado do corpo, com as palmas voltadas para as coxas ou para frente.", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído.", "Comece com os braços esticados."], ["Dobre um cotovelo, girando a palma para cima durante a subida, até o halter chegar ao ombro.", "Desça devagar até esticar o braço e faça o outro lado.", "Alterne os lados, sem balançar o tronco."], ["Balançar o tronco.", "Levar o cotovelo à frente.", "Subir rápido demais."]],
  "Rosca martelo": ["Bíceps, braquial e antebraço", ["Em pé, segure um halter em cada mão ao lado do corpo, com as palmas voltadas uma para a outra (pegada neutra, como um martelo).", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído.", "Comece com os braços esticados."], ["Dobre os cotovelos levando os halteres até os ombros, mantendo as palmas voltadas uma para a outra.", "Aperte o bíceps e desça devagar até esticar os braços.", "Faça os dois braços juntos ou alternados."], ["Balançar o tronco.", "Levar os cotovelos à frente.", "Carga alta demais."]],
  "Rosca martelo na corda": ["Bíceps, braquial e antebraço", ["Fique em pé, de frente para a polia baixa, com a corda presa. Segure as pontas da corda com as palmas voltadas uma para a outra.", "Mantenha os cotovelos junto ao corpo e as costas retas.", "Comece com os braços esticados."], ["Dobre os cotovelos levando as mãos aos ombros, mantendo as palmas voltadas uma para a outra.", "Aperte o bíceps e desça devagar até esticar os braços.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Levar os cotovelos à frente.", "Soltar o peso na descida."]],
  "Rosca inclinada": ["Bíceps (principalmente a cabeça longa)", ["Sente em um banco inclinado (cerca de 45° a 60°), com as costas apoiadas. Segure um halter em cada mão, com os braços pendurados ao lado do corpo e as palmas voltadas para frente.", "Mantenha os ombros para trás e os cotovelos apontando para baixo.", "Comece com os braços esticados, alongando bem o bíceps."], ["Dobre os cotovelos levando os halteres aos ombros, sem mover os cotovelos para frente.", "Aperte o bíceps no alto e desça devagar, em cerca de 3 segundos, até esticar os braços.", "Use carga leve a moderada."], ["Levar os cotovelos à frente.", "Balançar o tronco.", "Carga alta que perde a amplitude."]],
  "Rosca scott": ["Bíceps (principalmente a parte de baixo)", ["Sente no banco Scott, com a parte de trás dos braços apoiada na almofada e o peito encostado no apoio. Segure a barra W com as palmas para cima.", "Comece com os braços quase esticados (não trave os cotovelos totalmente).", "Mantenha os ombros para trás."], ["Dobre os cotovelos levando a barra até os ombros, sem tirar os braços da almofada.", "Aperte o bíceps e desça devagar, em cerca de 3 segundos, até quase esticar os braços.", "Mantenha o movimento controlado."], ["Soltar o peso na descida (risco para o cotovelo).", "Tirar o peito do apoio.", "Esticar totalmente os cotovelos com força."]],
  "Rosca scott na máquina": ["Bíceps (principalmente a parte de baixo)", ["Ajuste o banco para que os ombros fiquem acima da almofada. Sente com a parte de trás dos braços apoiada e segure as alças.", "Comece com os braços quase esticados.", "Mantenha o peito encostado no apoio."], ["Dobre os cotovelos levando as alças aos ombros, sem tirar os braços da almofada.", "Aperte o bíceps e desça devagar até quase esticar os braços.", "Não deixe o peso bater."], ["Soltar o peso na descida.", "Tirar o peito do apoio.", "Esticar totalmente os cotovelos com força."]],
  "Rosca concentrada": ["Bíceps (pico) e antebraço", ["Sente em um banco com as pernas abertas. Apoie a parte de trás do braço (perto do cotovelo) na parte interna da coxa e segure um halter com a palma voltada para cima.", "Incline levemente o tronco à frente, com as costas retas.", "Comece com o braço esticado."], ["Dobre o cotovelo levando o halter ao ombro, sem mover o braço da coxa.", "Aperte o bíceps no alto e desça devagar até esticar o braço.", "Faça todas as repetições de um lado e depois troque."], ["Balançar o tronco.", "Mover o cotovelo para frente.", "Carga alta demais."]],
  "Rosca spider": ["Bíceps (principalmente a parte de baixo e o pico)", ["Deite de bruços em um banco inclinado (cerca de 45°), com o peito apoiado e os braços pendurados à frente.", "Segure uma barra W (ou halteres) com as palmas voltadas para cima.", "Comece com os braços quase esticados."], ["Dobre os cotovelos levando a barra aos ombros, sem balançar o corpo.", "Aperte o bíceps e desça devagar até quase esticar os braços.", "Mantenha o peito apoiado."], ["Balançar o corpo.", "Soltar o peso na descida.", "Carga alta demais."]],
  "Rosca na polia": ["Bíceps e antebraço", ["Em pé, de frente para a polia baixa, segure a barra reta (ou a corda) com as palmas voltadas para cima.", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído.", "Comece com os braços esticados."], ["Dobre os cotovelos levando as mãos aos ombros, sem mover os cotovelos para frente.", "Aperte o bíceps e desça devagar até esticar os braços, mantendo a tensão do cabo.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Levar os cotovelos à frente.", "Soltar o peso na descida."]],
  "Rosca Bayesian na polia": ["Bíceps (principalmente a cabeça longa)", ["Fique em pé de costas para a polia baixa, segure a alça com uma mão e leve o braço levemente para trás do corpo, esticado.", "Dê um passo à frente e mantenha o tronco reto ou levemente inclinado à frente.", "Comece com o braço esticado e levemente atrás do corpo."], ["Dobre o cotovelo levando a mão ao ombro, sem mover o cotovelo para frente.", "Aperte o bíceps e desça devagar até esticar o braço, alongando o bíceps.", "Faça todas as repetições de um lado e depois troque."], ["Levar o cotovelo à frente.", "Balançar o tronco.", "Soltar o peso na descida."]],
  "Rosca 21": ["Bíceps e antebraço", ["Em pé, segure uma barra (reta ou W) com as palmas voltadas para cima, na largura dos ombros.", "Mantenha os cotovelos junto ao corpo e as costas retas.", "Use carga leve, pois o exercício cansa muito."], ["Faça 7 repetições da metade de baixo do movimento (de esticado até 90°).", "Em seguida, faça 7 repetições da metade de cima (de 90° até os ombros).", "Termine com 7 repetições completas. Tudo sem parar, em uma só série."], ["Usar carga alta demais.", "Balançar o tronco.", "Perder a contagem e a técnica no final."]],
  "Tríceps pulley": ["Tríceps", ["Em pé, de frente para a polia alta, segure a barra reta com as mãos na largura dos ombros e as palmas voltadas para baixo.", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído. Incline o tronco levemente à frente.", "Comece com os cotovelos dobrados a 90°."], ["Estenda os cotovelos empurrando a barra para baixo, até esticar os braços.", "Aperte o tríceps no final e volte devagar, em cerca de 3 segundos, até os cotovelos dobrarem a 90°.", "Mantenha os cotovelos parados junto ao corpo."], ["Abrir os cotovelos.", "Balançar o tronco e usar o peso do corpo.", "Subir demais na volta."]],
  "Tríceps corda": ["Tríceps", ["Em pé, de frente para a polia alta com a corda presa, segure as pontas com as palmas voltadas uma para a outra.", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído.", "Comece com os cotovelos dobrados a 90°."], ["Estenda os cotovelos empurrando a corda para baixo e abrindo as mãos para os lados no final, até esticar os braços.", "Aperte o tríceps e volte devagar até os cotovelos dobrarem a 90°.", "Mantenha os cotovelos parados."], ["Abrir os cotovelos.", "Balançar o tronco.", "Subir demais na volta."]],
  "Tríceps unilateral na polia": ["Tríceps", ["Em pé, de frente para a polia alta, segure a alça com uma mão, com a palma voltada para baixo (ou para dentro).", "Mantenha o cotovelo junto ao corpo, o tronco reto e o abdômen contraído.", "Comece com o cotovelo dobrado a 90°."], ["Estenda o cotovelo empurrando a alça para baixo, até esticar o braço.", "Aperte o tríceps e volte devagar até o cotovelo dobrar a 90°.", "Faça todas as repetições de um lado e depois troque."], ["Abrir o cotovelo.", "Balançar o tronco.", "Soltar o peso na volta."]],
  "Tríceps testa": ["Tríceps", ["Deite em um banco reto com uma barra W (ou reta) nas mãos, as palmas voltadas para frente e os braços esticados acima do peito.", "Mantenha os pés firmes no chão e as costas apoiadas.", "Mantenha os cotovelos apontando para o teto."], ["Dobre só os cotovelos, descendo a barra em direção à testa (ou um pouco atrás da cabeça), sem mover os braços.", "Estenda os cotovelos e volte à posição inicial, aperte o tríceps.", "Faça o movimento devagar."], ["Abrir os cotovelos.", "Mover os braços para frente e para trás.", "Carga alta sem ajuda, com risco de bater a barra na cabeça."]],
  "Tríceps testa com halteres": ["Tríceps", ["Deite em um banco reto com um halter em cada mão, com as palmas voltadas uma para a outra e os braços esticados acima do peito.", "Mantenha os pés firmes e as costas apoiadas.", "Mantenha os cotovelos apontando para o teto."], ["Dobre só os cotovelos, descendo os halteres ao lado da cabeça, sem mover os braços.", "Estenda os cotovelos até esticar os braços, apertando o tríceps.", "Faça o movimento devagar."], ["Abrir os cotovelos.", "Mover os braços.", "Carga alta demais, com risco de bater o halter na cabeça."]],
  "Tríceps francês": ["Tríceps (principalmente a cabeça longa)", ["Sentado ou em pé, segure uma barra W (ou um halter) com as duas mãos acima da cabeça, com os braços esticados.", "Mantenha os cotovelos apontando para frente e próximos da cabeça.", "Mantenha o abdômen contraído."], ["Dobre os cotovelos descendo o peso atrás da cabeça, sem mover os braços.", "Estenda os cotovelos até esticar os braços, apertando o tríceps.", "Faça o movimento devagar."], ["Abrir os cotovelos.", "Arquear a lombar.", "Carga alta demais."]],
  "Tríceps francês com halter": ["Tríceps (principalmente a cabeça longa)", ["Sentado ou em pé, segure um halter com as duas mãos (em volta do disco de cima), acima da cabeça, com os braços esticados.", "Mantenha os cotovelos apontando para frente e próximos da cabeça.", "Mantenha o abdômen contraído."], ["Dobre os cotovelos descendo o halter atrás da cabeça, sem mover os braços.", "Estenda os cotovelos até esticar os braços, apertando o tríceps.", "Faça o movimento devagar."], ["Abrir os cotovelos.", "Arquear a lombar.", "Soltar o peso na descida."]],
  "Tríceps corda acima da cabeça": ["Tríceps (principalmente a cabeça longa)", ["De costas para a polia (altura média ou baixa), segure a corda com as duas mãos atrás da cabeça. Dê um passo à frente, com um pé na frente do outro.", "Incline levemente o tronco à frente, com os cotovelos apontando para frente.", "Comece com os cotovelos dobrados."], ["Estenda os cotovelos levando a corda para frente e para cima, até esticar os braços.", "Aperte o tríceps e volte devagar até os cotovelos dobrarem.", "Mantenha o tronco e os cotovelos parados."], ["Abrir os cotovelos.", "Balançar o tronco.", "Soltar o peso na volta."]],
  "Tríceps banco": ["Tríceps, ombros (frente) e peito", ["Sente na borda de um banco, com as mãos apoiadas ao lado do quadril e os dedos para frente. Leve o quadril para fora do banco.", "Estique as pernas à frente (mais difícil) ou dobre os joelhos (mais fácil).", "Mantenha os braços esticados e as costas perto do banco."], ["Desça dobrando os cotovelos até cerca de 90°, mantendo as costas perto do banco.", "Empurre o banco para esticar os braços, apertando o tríceps.", "Mantenha os cotovelos apontando para trás, sem abrir."], ["Descer demais e forçar o ombro.", "Afastar as costas do banco.", "Abrir os cotovelos."]],
  "Tríceps coice": ["Tríceps", ["Apoie uma mão e o joelho do mesmo lado em um banco, com as costas retas. Segure um halter com a outra mão, com o cotovelo dobrado a 90° e junto ao corpo.", "Mantenha o braço do halter paralelo ao tronco.", "Mantenha o pescoço alinhado com a coluna."], ["Estenda o cotovelo levando o halter para trás, até esticar o braço, apertando o tríceps.", "Volte devagar, dobrando o cotovelo até 90°.", "Faça todas as repetições de um lado e depois troque."], ["Mover o braço (só o antebraço se move).", "Balançar o tronco.", "Carga alta demais."]],
  "Tríceps na máquina": ["Tríceps", ["Sente na máquina com as costas apoiadas e os cotovelos junto ao corpo. Segure as alças ou apoie os antebraços, conforme o aparelho.", "Mantenha os pés firmes no chão.", "Comece com os cotovelos dobrados."], ["Estenda os cotovelos empurrando as alças até esticar os braços, apertando o tríceps.", "Volte devagar até os cotovelos dobrarem.", "Mantenha os cotovelos parados."], ["Abrir os cotovelos.", "Soltar o peso na volta.", "Descolar as costas do encosto."]],
  "Mergulho na máquina": ["Tríceps e peito (parte de baixo)", ["Sente na máquina de mergulho com as costas apoiadas e os pés firmes. Segure as alças com as palmas voltadas para dentro.", "Mantenha os cotovelos junto ao corpo.", "Comece com os cotovelos dobrados."], ["Empurre as alças para baixo estendendo os cotovelos, até esticar os braços.", "Volte devagar até os cotovelos dobrarem.", "Mantenha os ombros longe das orelhas."], ["Subir os ombros.", "Abrir os cotovelos.", "Soltar o peso na volta."]],
  "Flexão diamante": ["Tríceps, peito (parte de dentro) e ombros (frente)", ["Apoie as mãos no chão, juntas sob o peito, formando um losango com os polegares e os indicadores. Os pés ficam juntos ou levemente afastados.", "Mantenha o corpo reto, da cabeça aos calcanhares, com o abdômen e o glúteo contraídos.", "Se for difícil, apoie os joelhos."], ["Desça dobrando os cotovelos, mantendo-os junto ao corpo, até o peito chegar perto das mãos.", "Empurre o chão e volte até esticar os braços.", "Mantenha o corpo reto."], ["Deixar o quadril cair.", "Abrir os cotovelos.", "Pessoas com dor no punho podem apoiar as mãos em um banco para facilitar."]],
  "Supino fechado": ["Tríceps, peito e ombros (frente)", ["Deite no banco reto com os olhos alinhados com a barra, os pés firmes e as escápulas juntas.", "Segure a barra com as mãos na largura dos ombros (não mais fechadas que isso, para não forçar os punhos).", "Tire a barra do suporte com os braços esticados."], ["Desça a barra devagar até tocar de leve a parte de baixo do peito, com os cotovelos junto ao corpo.", "Empurre a barra para cima até esticar os braços.", "Mantenha o quadril no banco."], ["Pegada fechada demais (força o punho).", "Abrir os cotovelos.", "Carga alta sem ajuda para recolocar a barra."]],
  "Rosca punho": ["Antebraço (parte de dentro: flexores)", ["Sente em um banco e apoie os antebraços nas coxas, com as palmas voltadas para cima e os punhos para fora dos joelhos.", "Segure uma barra (ou halteres) com as mãos na largura dos ombros.", "Deixe a barra descer até os dedos, abrindo levemente as mãos."], ["Feche as mãos e dobre só os punhos para cima, levando a barra o mais alto que conseguir.", "Segure um instante e desça devagar, abrindo as mãos até a barra chegar nos dedos.", "Mantenha os antebraços apoiados e parados."], ["Mover os antebraços.", "Usar carga alta demais.", "Fazer rápido, sem controle."]],
  "Rosca punho inversa": ["Antebraço (parte de fora: extensores)", ["Sente em um banco e apoie os antebraços nas coxas, com as palmas voltadas para baixo e os punhos para fora dos joelhos.", "Segure uma barra (ou halteres) com as mãos na largura dos ombros.", "Comece com os punhos dobrados para baixo."], ["Levante as costas das mãos dobrando só os punhos para cima.", "Segure um instante e desça devagar.", "Use carga leve, pois esses músculos são pequenos."], ["Usar carga alta.", "Mover os antebraços.", "Fazer rápido."]],
  "Rosca punho atrás das costas": ["Antebraço (flexores) e pegada", ["Em pé, segure uma barra atrás das coxas, com as palmas voltadas para trás e as mãos na largura dos ombros.", "Mantenha as costas retas e os braços esticados.", "Use uma barra leve."], ["Deixe a barra rolar até a ponta dos dedos, abrindo as mãos.", "Feche as mãos e suba a barra usando punhos e dedos.", "Repita devagar, sem balançar os braços."], ["Carga alta demais, com risco de a barra cair.", "Balançar o corpo."]],
  "Rosca inversa": ["Antebraço, braquiorradial e bíceps", ["Em pé, segure a barra (reta ou W) com as palmas voltadas para baixo, na largura dos ombros.", "Mantenha os cotovelos junto ao corpo, as costas retas e o abdômen contraído.", "Comece com os braços esticados."], ["Dobre os cotovelos levando a barra até os ombros, mantendo os punhos retos.", "Desça devagar até esticar os braços.", "Use carga mais leve que na rosca direta."], ["Balançar o tronco.", "Dobrar os punhos.", "Carga alta demais."]],
  "Rosca inversa na polia": ["Antebraço, braquiorradial e bíceps", ["Em pé, de frente para a polia baixa, segure a barra reta com as palmas voltadas para baixo.", "Mantenha os cotovelos junto ao corpo e as costas retas.", "Comece com os braços esticados."], ["Dobre os cotovelos levando a barra aos ombros, mantendo os punhos retos.", "Desça devagar até esticar os braços, mantendo a tensão do cabo.", "Mantenha o tronco parado."], ["Balançar o tronco.", "Dobrar os punhos.", "Soltar o peso na descida."]],
  "Rolo de punho": ["Antebraço (flexores e extensores) e pegada", ["Em pé, segure o rolo com as duas mãos, com os braços esticados à frente na altura dos ombros e as palmas voltadas para baixo. Uma corda com um peso fica pendurada no rolo.", "Mantenha as costas retas.", "Comece com o peso embaixo, com a corda desenrolada."], ["Gire os punhos enrolando a corda no rolo, até o peso subir por completo.", "Desenrole devagar, controlando o peso até embaixo.", "Mantenha os braços esticados e parados."], ["Abaixar os braços.", "Usar carga alta demais.", "Soltar a corda rápido."]],
  "Caminhada do fazendeiro": ["Antebraço, pegada, trapézio e abdômen", ["Fique em pé entre dois halteres pesados (ou kettlebells). Dobre o quadril e os joelhos, mantendo as costas retas, e segure um peso em cada mão.", "Levante-se com os pesos ao lado do corpo, com os ombros para trás e o peito aberto.", "Contraia o abdômen."], ["Caminhe com passos curtos e firmes por uma distância ou por um tempo definido.", "Mantenha a postura reta, sem balançar o corpo e sem deixar os ombros caírem à frente.", "Ao terminar, abaixe os pesos com as costas retas."], ["Curvar as costas.", "Balançar o corpo.", "Carga alta demais, com risco de queda dos pesos."]],
  "Dead hang (pendurar na barra)": ["Antebraço, pegada, ombros e costas", ["Segure uma barra fixa com as palmas voltadas para frente, na largura dos ombros. Se precisar, use um banco para subir até a barra.", "Pendure-se com os braços esticados, os ombros relaxados e o abdômen contraído.", "Cruze os pés atrás ou deixe as pernas retas."], ["Fique pendurado o máximo de tempo que conseguir, respirando normalmente.", "Ao terminar, desça com cuidado, apoiando os pés.", "Aumente o tempo aos poucos."], ["Soltar de repente.", "Pessoas com dor no ombro devem parar e falar com um profissional."]],
  "Agachamento livre": ["Quadríceps, glúteos, parte de trás das coxas e lombar", ["Posicione a barra apoiada nas costas, sobre os ombros (na parte de cima do trapézio), e segure-a com as mãos um pouco mais abertas que os ombros.", "Tire a barra do suporte e dê um passo para trás. Fique com os pés na largura dos ombros e as pontas levemente viradas para fora.", "Mantenha o peito aberto, as costas retas e o abdômen contraído."], ["Desça levando o quadril para trás e para baixo, como se fosse sentar em uma cadeira, até as coxas ficarem paralelas ao chão (ou o máximo que conseguir com as costas retas).", "Mantenha os joelhos na direção dos pés e os calcanhares no chão.", "Suba empurrando o chão com os pés, estendendo quadril e joelhos juntos."], ["Curvar as costas.", "Joelhos entrando para dentro.", "Tirar os calcanhares do chão.", "Carga alta sem trave de segurança. Peça orientação de um profissional."]],
  "Agachamento frontal": ["Quadríceps, glúteos e abdômen", ["Apoie a barra na frente dos ombros, sobre as clavículas, com os cotovelos altos e apontando para frente. Segure a barra com os dedos (ou cruze os braços).", "Fique com os pés na largura dos ombros e as pontas levemente viradas para fora.", "Mantenha o peito aberto e o tronco bem reto."], ["Desça levando o quadril para baixo, mantendo o tronco reto e os cotovelos altos, até as coxas ficarem paralelas ao chão.", "Mantenha os joelhos na direção dos pés.", "Suba empurrando o chão com os pés."], ["Deixar os cotovelos caírem.", "Curvar o tronco à frente.", "Tirar os calcanhares do chão.", "Carga alta sem ajuda."]],
  "Agachamento sumô": ["Glúteos, parte interna das coxas e quadríceps", ["Fique com os pés bem afastados (mais que os ombros) e as pontas viradas para fora, cerca de 45°.", "Segure um halter (ou kettlebell) à frente do corpo, com os braços esticados.", "Mantenha o peito aberto e o tronco reto."], ["Desça levando o quadril para baixo, com os joelhos na direção dos pés, até as coxas ficarem paralelas ao chão.", "Mantenha o tronco reto.", "Suba empurrando o chão e contraindo glúteos e a parte interna das coxas."], ["Joelhos entrando para dentro.", "Curvar as costas.", "Tirar os calcanhares do chão."]],
  "Agachamento goblet": ["Quadríceps, glúteos e abdômen", ["Segure um halter (ou kettlebell) junto ao peito, com as duas mãos, e os cotovelos apontando para baixo.", "Fique com os pés na largura dos ombros e as pontas levemente viradas para fora.", "Mantenha o peito aberto e o tronco reto."], ["Desça levando o quadril para baixo e os cotovelos entre os joelhos, mantendo o tronco reto.", "Desça até as coxas ficarem paralelas ao chão (ou mais, se conseguir).", "Suba empurrando o chão."], ["Curvar as costas.", "Joelhos entrando para dentro.", "Tirar os calcanhares do chão.", "Bom para aprender o movimento do agachamento."]],
  "Agachamento no smith": ["Quadríceps, glúteos e parte de trás das coxas", ["Posicione a barra do smith nas costas, sobre os ombros, e gire para destravar. Fique com os pés um pouco à frente da barra, na largura dos ombros.", "Mantenha o peito aberto, as costas retas e o abdômen contraído.", "Com os pés mais à frente, a exigência é maior no glúteo; mais atrás, maior no quadríceps."], ["Desça levando o quadril para trás e para baixo até as coxas ficarem paralelas ao chão.", "Mantenha os joelhos na direção dos pés e os calcanhares no chão.", "Suba empurrando o chão. Trave a barra ao terminar."], ["Pés muito juntos à barra, forçando o joelho.", "Curvar as costas.", "Esquecer de travar a barra."]],
  "Agachamento na máquina": ["Quadríceps, glúteos e parte de trás das coxas", ["Posicione os ombros sob as almofadas e os pés na plataforma, na largura dos ombros. Destrave a máquina.", "Mantenha o peito aberto e as costas apoiadas no encosto.", "Mantenha o abdômen contraído."], ["Desça levando o quadril para baixo, mantendo as costas apoiadas, até onde conseguir com conforto.", "Mantenha os joelhos na direção dos pés.", "Suba empurrando a plataforma com os pés, sem travar os joelhos."], ["Joelhos entrando para dentro.", "Descolar as costas.", "Travar os joelhos no alto."]],
  "Agachamento búlgaro": ["Quadríceps, glúteos e parte de trás das coxas", ["Fique de costas para um banco, a uns dois passos de distância. Apoie o peito do pé de trás no banco e mantenha o pé da frente firme no chão.", "Segure um halter em cada mão (ou use só o peso do corpo).", "Mantenha o tronco reto e o abdômen contraído."], ["Desça dobrando o joelho da frente e levando o quadril para baixo, até a coxa ficar paralela ao chão.", "Mantenha o joelho da frente na direção do pé, sem passar muito da ponta.", "Suba empurrando o chão com a perna da frente. Faça todas as repetições de um lado e depois troque."], ["Pé muito perto do banco.", "Joelho entrando para dentro.", "Perder o equilíbrio por carga alta demais."]],
  "Hack squat": ["Quadríceps e glúteos", ["Posicione os ombros sob as almofadas e as costas apoiadas no encosto. Os pés ficam na plataforma, na largura dos ombros (mais baixos foca mais o quadríceps).", "Destrave a máquina e mantenha o abdômen contraído.", "Mantenha o peito aberto."], ["Desça dobrando os joelhos e levando o quadril para baixo, até as coxas ficarem paralelas à plataforma (ou mais).", "Mantenha os joelhos na direção dos pés.", "Suba empurrando a plataforma, sem travar os joelhos."], ["Descolar as costas.", "Joelhos entrando para dentro.", "Travar os joelhos no alto."]],
  "Leg press 45": ["Quadríceps, glúteos e parte de trás das coxas", ["Sente na máquina com as costas e a cabeça apoiadas e os pés na plataforma, na largura dos ombros, com as pontas levemente viradas para fora.", "Destrave a máquina e segure nas alças.", "Mantenha o quadril encostado no encosto."], ["Desça dobrando os joelhos até cerca de 90° (ou um pouco mais), sem tirar o quadril do encosto.", "Empurre a plataforma com os pés, estendendo os joelhos, sem travá-los.", "Mantenha os joelhos na direção dos pés."], ["Descer demais, tirando o quadril do encosto.", "Travar os joelhos no alto.", "Joelhos entrando para dentro.", "Carga alta e amplitude curta."]],
  "Leg press horizontal": ["Quadríceps, glúteos e parte de trás das coxas", ["Sente na máquina com as costas apoiadas e os pés na plataforma, na largura dos ombros, com as pontas levemente viradas para fora.", "Segure nas alças e mantenha o quadril encostado no encosto.", "Destrave a máquina."], ["Desça dobrando os joelhos até cerca de 90° sem tirar o quadril do encosto.", "Empurre a plataforma estendendo os joelhos, sem travá-los.", "Mantenha os joelhos na direção dos pés."], ["Descer demais.", "Travar os joelhos.", "Joelhos entrando para dentro."]],
  "Leg press unilateral": ["Quadríceps, glúteos e parte de trás das coxas", ["Sente na máquina com as costas apoiadas e apoie só um pé no centro da plataforma. O outro pé fica no chão ou apoiado ao lado.", "Segure nas alças e mantenha o quadril encostado no encosto.", "Use carga menor que a usada com os dois pés."], ["Desça dobrando o joelho até cerca de 90°, sem tirar o quadril do encosto.", "Empurre a plataforma estendendo o joelho, sem travá-lo.", "Faça todas as repetições de um lado e depois troque."], ["Carga alta demais.", "Travar o joelho.", "Joelho entrando para dentro."]],
  "Cadeira extensora": ["Quadríceps", ["Sente na máquina com as costas apoiadas e ajuste o apoio para ficar na altura dos tornozelos (parte de baixo das canelas). O joelho fica alinhado com o eixo da máquina.", "Segure nas alças.", "Comece com os joelhos dobrados a 90°."], ["Estenda as pernas até quase esticar os joelhos, apertando o quadríceps no alto.", "Volte devagar, em cerca de 3 segundos, sem deixar o peso bater.", "Mantenha as costas e o quadril apoiados."], ["Soltar o peso na descida.", "Travar os joelhos com força.", "Levantar o quadril do assento."]],
  "Cadeira extensora unilateral": ["Quadríceps", ["Sente na máquina com as costas apoiadas e ajuste o apoio na altura dos tornozelos. Use só uma perna por vez.", "Segure nas alças.", "Comece com o joelho dobrado a 90°."], ["Estenda a perna até quase esticar o joelho, apertando o quadríceps.", "Volte devagar, sem deixar o peso bater.", "Faça todas as repetições de um lado e depois troque."], ["Levantar o quadril.", "Soltar o peso.", "Usar carga alta demais."]],
  "Sissy squat": ["Quadríceps (principalmente o reto femoral)", ["Fique em pé, segurando em um apoio firme. Suba na ponta dos pés, com os pés na largura do quadril.", "Mantenha o abdômen contraído e as costas retas.", "Comece sem carga. É um exercício avançado e exige cuidado com os joelhos."], ["Incline o tronco para trás e dobre os joelhos levando-os para frente, descendo devagar, mantendo o corpo em linha do joelho à cabeça.", "Desça até onde conseguir com conforto.", "Suba devagar, voltando à posição inicial."], ["Descer rápido.", "Usar carga alta demais.", "Pessoas com dor no joelho devem evitar e falar com um profissional."]],
  "Avanço": ["Quadríceps, glúteos e parte de trás das coxas", ["Fique em pé com os pés na largura do quadril. Segure um halter em cada mão ao lado do corpo (ou use só o peso do corpo).", "Mantenha o tronco reto e o abdômen contraído.", "Olhe para frente."], ["Dê um passo grande à frente e desça dobrando os dois joelhos, até o joelho de trás quase tocar o chão. O joelho da frente fica a 90°, sobre o tornozelo.", "Empurre o chão com o pé da frente e volte à posição inicial.", "Repita alternando as pernas ou faça todas as repetições de um lado."], ["Joelho da frente passando muito da ponta do pé.", "Inclinar o tronco à frente.", "Joelho entrando para dentro."]],
  "Passada": ["Quadríceps, glúteos e parte de trás das coxas", ["Fique em pé com os pés na largura do quadril. Segure um halter em cada mão ao lado do corpo (ou use só o peso do corpo).", "Mantenha o tronco reto e o abdômen contraído.", "Use um espaço livre à frente."], ["Dê um passo grande à frente e desça dobrando os dois joelhos, até o joelho de trás quase tocar o chão.", "Empurre o chão com o pé da frente e traga o pé de trás para dar o próximo passo, alternando as pernas e andando à frente.", "Faça o número de passos definido."], ["Passos curtos demais.", "Inclinar o tronco à frente.", "Perder o equilíbrio por carga alta demais."]],
  "Afundo no smith": ["Quadríceps, glúteos e parte de trás das coxas", ["Posicione a barra do smith nas costas, sobre os ombros, e destrave. Dê um passo à frente, com um pé à frente da barra e o outro atrás.", "Mantenha o tronco reto e o abdômen contraído.", "Os pés ficam na largura do quadril."], ["Desça dobrando os dois joelhos até o joelho de trás quase tocar o chão.", "Suba empurrando com o calcanhar do pé da frente.", "Faça todas as repetições de um lado e depois troque. Trave a barra ao terminar."], ["Joelho da frente passando muito da ponta do pé.", "Inclinar o tronco à frente.", "Esquecer de travar a barra."]],
  "Step-up (subida no banco)": ["Quadríceps, glúteos e parte de trás das coxas", ["Fique de frente para um banco ou caixa firme, com altura que deixe o joelho a cerca de 90° ao apoiar o pé. Segure um halter em cada mão (ou use só o peso do corpo).", "Apoie um pé inteiro sobre o banco.", "Mantenha o tronco reto e o abdômen contraído."], ["Suba empurrando o banco com a perna de cima, sem se impulsionar com a perna de baixo, até ficar em pé em cima do banco.", "Desça devagar, controlando, até o pé de trás tocar o chão.", "Faça todas as repetições de um lado e depois troque."], ["Impulsionar com a perna de baixo.", "Banco alto demais.", "Inclinar o tronco à frente."]],
  "Mesa flexora": ["Parte de trás das coxas (posteriores) e panturrilha", ["Deite de bruços na máquina, com os joelhos logo após a borda do banco e o apoio sobre a parte de trás dos tornozelos.", "Segure nas alças e mantenha o quadril encostado no banco.", "Comece com as pernas esticadas."], ["Dobre os joelhos levando os calcanhares em direção ao glúteo, apertando a parte de trás das coxas.", "Volte devagar, em cerca de 3 segundos, até esticar as pernas, sem deixar o peso bater.", "Mantenha o quadril no banco."], ["Levantar o quadril do banco.", "Soltar o peso na volta.", "Carga alta que faz o corpo balançar."]],
  "Mesa flexora unilateral": ["Parte de trás das coxas (posteriores)", ["Deite de bruços na máquina e apoie o tornozelo de uma perna sob o apoio. A outra perna fica relaxada.", "Segure nas alças e mantenha o quadril encostado no banco.", "Comece com a perna esticada."], ["Dobre o joelho levando o calcanhar em direção ao glúteo.", "Volte devagar até esticar a perna.", "Faça todas as repetições de um lado e depois troque."], ["Levantar o quadril.", "Soltar o peso.", "Usar carga alta demais."]],
  "Cadeira flexora": ["Parte de trás das coxas (posteriores)", ["Sente na máquina com as costas apoiadas e ajuste o apoio para ficar sobre a parte de trás dos tornozelos. Prenda as coxas com a almofada.", "Segure nas alças.", "Comece com as pernas esticadas à frente."], ["Dobre os joelhos puxando o apoio para baixo e para trás, apertando a parte de trás das coxas.", "Volte devagar, em cerca de 3 segundos, até esticar as pernas.", "Mantenha as costas apoiadas."], ["Soltar o peso na volta.", "Descolar as costas.", "Levantar o quadril do assento."]],
  "Cadeira flexora unilateral": ["Parte de trás das coxas (posteriores)", ["Sente na máquina com as costas apoiadas e prenda as coxas. Apoie o tornozelo de uma perna sob o apoio.", "Segure nas alças.", "Comece com a perna esticada."], ["Dobre o joelho puxando o apoio para baixo e para trás.", "Volte devagar até esticar a perna.", "Faça todas as repetições de um lado e depois troque."], ["Descolar as costas.", "Soltar o peso.", "Carga alta demais."]],
  "Flexora em pé": ["Parte de trás das coxas (posteriores)", ["Fique em pé na máquina, com o corpo apoiado e uma perna livre. Posicione o apoio sobre a parte de trás do tornozelo da perna que vai trabalhar.", "Segure nas alças e mantenha o corpo estável.", "Comece com a perna esticada."], ["Dobre o joelho levando o calcanhar em direção ao glúteo.", "Volte devagar até esticar a perna, sem balançar o corpo.", "Faça todas as repetições de um lado e depois troque."], ["Balançar o corpo.", "Arquear a lombar.", "Soltar o peso na volta."]],
  "Stiff": ["Parte de trás das coxas (posteriores), glúteos e lombar", ["Em pé, segure uma barra à frente das coxas, com as mãos na largura dos ombros e as palmas para baixo. Os pés ficam na largura do quadril.", "Dobre levemente os joelhos e mantenha essa dobra durante todo o exercício.", "Mantenha as costas retas e o peito aberto."], ["Leve o quadril para trás, descendo a barra rente às pernas, até sentir a parte de trás das coxas alongar (geralmente na altura dos joelhos ou da canela).", "Mantenha as costas retas durante todo o movimento.", "Suba contraindo glúteos e posteriores, levando o quadril à frente."], ["Curvar as costas (risco para a lombar).", "Afastar a barra das pernas.", "Dobrar os joelhos como no agachamento."]],
  "Stiff com halteres": ["Parte de trás das coxas (posteriores), glúteos e lombar", ["Em pé, segure um halter em cada mão à frente das coxas, com as palmas voltadas para o corpo. Os pés ficam na largura do quadril.", "Dobre levemente os joelhos e mantenha essa dobra.", "Mantenha as costas retas e o peito aberto."], ["Leve o quadril para trás, descendo os halteres rente às pernas, até sentir a parte de trás das coxas alongar.", "Mantenha as costas retas durante todo o movimento.", "Suba contraindo glúteos e posteriores, levando o quadril à frente."], ["Curvar as costas.", "Afastar os halteres das pernas.", "Dobrar demais os joelhos."]],
  "Levantamento terra romeno": ["Parte de trás das coxas (posteriores), glúteos e lombar", ["Em pé, segure uma barra à frente das coxas, com as mãos na largura dos ombros. Os pés ficam na largura do quadril, com os joelhos levemente dobrados.", "Mantenha as costas retas e o peito aberto.", "Comece com a barra à frente das coxas."], ["Leve o quadril para trás, descendo a barra rente às pernas, até sentir a parte de trás das coxas alongar (geralmente abaixo dos joelhos).", "Mantenha as costas retas durante todo o movimento.", "Suba contraindo glúteos e posteriores, levando o quadril à frente."], ["Curvar as costas.", "Afastar a barra das pernas.", "Descer além do ponto em que as costas ficam retas."]],
  "Levantamento terra sumô": ["Glúteos, parte interna das coxas, costas e quadríceps", ["Fique com os pés bem afastados e as pontas viradas para fora, com a barra sobre o meio dos pés.", "Dobre o quadril e os joelhos e segure a barra com as mãos por dentro das pernas, na largura dos ombros ou mais fechada. As costas ficam retas e o peito aberto.", "Mantenha os braços esticados."], ["Empurre o chão com os pés, estendendo quadril e joelhos juntos, mantendo a barra rente ao corpo.", "Suba até ficar em pé, com o quadril esticado, sem se inclinar para trás.", "Desça controlando, levando o quadril para trás e dobrando os joelhos."], ["Curvar as costas.", "Joelhos entrando para dentro.", "Afastar a barra do corpo.", "Peça orientação de um profissional antes de colocar carga."]],
  "Good morning": ["Lombar, glúteos e parte de trás das coxas", ["Em pé, apoie uma barra nas costas, sobre os ombros, como no agachamento. Os pés ficam na largura dos ombros e os joelhos levemente dobrados.", "Mantenha o peito aberto e as costas retas.", "Use carga leve, pois exige cuidado com a lombar."], ["Leve o quadril para trás, inclinando o tronco à frente até ficar quase paralelo ao chão, mantendo as costas retas.", "Sinta a parte de trás das coxas alongar.", "Suba contraindo glúteos e posteriores, voltando à posição em pé."], ["Curvar as costas.", "Usar carga alta demais.", "Descer rápido.", "Pessoas com dor na lombar devem evitar e falar com um profissional."]],
  "Nordic curl": ["Parte de trás das coxas (posteriores)", ["Ajoelhe em uma almofada, com os tornozelos presos por um apoio (ou por um parceiro). O corpo fica reto, do joelho à cabeça.", "Cruze os braços à frente do peito ou deixe as mãos livres para amortecer.", "É um exercício avançado."], ["Desça o corpo para frente o mais devagar que conseguir, controlando com a parte de trás das coxas, mantendo o corpo reto.", "Quando não conseguir mais segurar, amorteça com as mãos no chão.", "Empurre o chão com as mãos para voltar à posição inicial."], ["Dobrar o quadril.", "Cair rápido demais.", "Fazer sem preparo, com risco de lesão."]],
  "Elevação pélvica": ["Glúteos e parte de trás das coxas", ["Deite de costas no chão, com os joelhos dobrados e os pés apoiados na largura do quadril, perto do glúteo. Os braços ficam ao lado do corpo.", "Contraia o abdômen e o glúteo antes de subir.", "Mantenha o pescoço relaxado."], ["Suba o quadril empurrando o chão com os calcanhares, contraindo o glúteo, até o corpo ficar alinhado do joelho aos ombros.", "Segure um instante no alto, apertando o glúteo.", "Desça devagar, sem encostar totalmente o quadril no chão."], ["Arquear a lombar no alto.", "Empurrar com a ponta dos pés.", "Descer rápido."]],
  "Hip thrust com barra": ["Glúteos e parte de trás das coxas", ["Sente no chão com as costas (na altura das escápulas) apoiadas na lateral de um banco. Role uma barra sobre o quadril, com uma proteção para não machucar.", "Dobre os joelhos e apoie os pés na largura do quadril, com os calcanhares firmes.", "Segure a barra com as mãos para estabilizar."], ["Suba o quadril empurrando o chão com os calcanhares e contraindo o glúteo, até o tronco e as coxas ficarem alinhados.", "Segure um instante, apertando o glúteo. O queixo fica levemente encostado no peito.", "Desça controlando, sem encostar o quadril no chão."], ["Arquear a lombar no alto.", "Empurrar com a ponta dos pés.", "Carga alta que impede a contração do glúteo."]],
  "Hip thrust na máquina": ["Glúteos e parte de trás das coxas", ["Sente na máquina com as costas apoiadas e o cinto (ou a almofada) sobre o quadril. Os pés ficam firmes na plataforma ou no chão, na largura do quadril.", "Segure nas alças.", "Mantenha o abdômen contraído."], ["Empurre o quadril para cima contraindo o glúteo, até o tronco e as coxas ficarem alinhados.", "Segure um instante, apertando o glúteo.", "Desça devagar, controlando o peso."], ["Arquear a lombar.", "Descer rápido.", "Empurrar com a ponta dos pés."]],
  "Ponte de glúteo": ["Glúteos e parte de trás das coxas", ["Deite de costas no chão, com os joelhos dobrados e os pés apoiados na largura do quadril. Os braços ficam ao lado do corpo.", "Contraia o abdômen e o glúteo.", "Mantenha o pescoço relaxado."], ["Suba o quadril contraindo o glúteo, até o corpo ficar alinhado do joelho aos ombros.", "Segure um instante no alto.", "Desça devagar, sem encostar totalmente no chão."], ["Arquear a lombar.", "Empurrar com a ponta dos pés.", "Descer rápido."]],
  "Glúteo na polia": ["Glúteos e parte de trás das coxas", ["Prenda a tornozeleira no tornozelo e ligue ao cabo da polia baixa. Fique de frente para a máquina, apoiando as mãos na estrutura.", "Incline levemente o tronco à frente, com as costas retas e o abdômen contraído.", "Mantenha a perna de apoio levemente dobrada."], ["Leve a perna de trabalho para trás, esticada ou levemente dobrada, contraindo o glúteo.", "Segure um instante no alto, sem arquear a lombar.", "Volte devagar, sem encostar o peso."], ["Arquear a lombar.", "Balançar o corpo.", "Subir a perna alto demais, sem contrair o glúteo."]],
  "Glúteo no smith": ["Glúteos e parte de trás das coxas", ["Apoie as mãos na barra do smith, na altura do peito, e fique de frente para ela. Apoie o pé de uma perna na barra, em ângulo de 90° do joelho.", "Mantenha o corpo estável e o abdômen contraído.", "A outra perna fica firme no chão."], ["Empurre a barra para cima com o pé, estendendo a perna e contraindo o glúteo.", "Segure um instante e volte devagar.", "Faça todas as repetições de um lado e depois troque."], ["Arquear a lombar.", "Descer rápido.", "Perder o equilíbrio."]],
  "Glúteo na máquina": ["Glúteos e parte de trás das coxas", ["Apoie o corpo na máquina, com o peito e as mãos nos apoios, e posicione uma perna na plataforma, com o pé apoiado.", "Mantenha o abdômen contraído.", "Comece com o joelho dobrado."], ["Empurre a plataforma para trás estendendo a perna e contraindo o glúteo.", "Segure um instante e volte devagar.", "Faça todas as repetições de um lado e depois troque."], ["Arquear a lombar.", "Balançar o corpo.", "Soltar o peso."]],
  "Extensão de quadril (4 apoios)": ["Glúteos e parte de trás das coxas", ["Apoie as mãos e os joelhos no chão, com as mãos sob os ombros e os joelhos sob o quadril. As costas ficam retas.", "Contraia o abdômen.", "Mantenha o pescoço alinhado com a coluna."], ["Estenda uma perna para trás e para cima, contraindo o glúteo, até a coxa ficar alinhada com o tronco.", "Segure um instante, sem arquear a lombar.", "Volte devagar e faça todas as repetições de um lado antes de trocar."], ["Arquear a lombar.", "Girar o quadril.", "Subir demais a perna."]],
  "Cadeira abdutora": ["Glúteos (parte de fora) e parte de fora do quadril", ["Sente na máquina com as costas apoiadas e as pernas apoiadas nas almofadas, na parte de fora dos joelhos.", "Segure nas alças.", "Comece com as pernas juntas."], ["Abra as pernas contra a resistência, até onde conseguir com conforto.", "Segure um instante e volte devagar, em cerca de 3 segundos.", "Mantenha as costas apoiadas."], ["Soltar o peso na volta.", "Descolar as costas.", "Usar o impulso."]],
  "Cadeira adutora": ["Parte interna das coxas (adutores)", ["Sente na máquina com as costas apoiadas e as pernas abertas, apoiadas nas almofadas, na parte de dentro dos joelhos.", "Segure nas alças.", "Ajuste a abertura para um alongamento confortável."], ["Junte as pernas contra a resistência, apertando a parte de dentro das coxas.", "Segure um instante e volte devagar, em cerca de 3 segundos.", "Mantenha as costas apoiadas."], ["Abrir demais, forçando a virilha.", "Soltar o peso na volta.", "Descolar as costas."]],
  "Abdução de quadril com elástico": ["Glúteos (parte de fora)", ["Coloque o elástico logo acima dos joelhos. Pode fazer em pé, sentado ou deitado de lado.", "Mantenha o tronco reto e o abdômen contraído.", "Comece com as pernas juntas."], ["Abra as pernas contra a resistência do elástico, até onde conseguir com conforto.", "Segure um instante e volte devagar, mantendo a tensão do elástico.", "Mantenha o tronco parado."], ["Soltar o elástico na volta.", "Girar o corpo.", "Usar um elástico forte demais."]],
  "Afundo": ["Glúteos, quadríceps e parte de trás das coxas", ["Em pé, com os pés na largura do quadril, segure um halter em cada mão (ou use só o peso do corpo).", "Mantenha o tronco reto e o abdômen contraído.", "Olhe para frente."], ["Dê um passo à frente e incline o tronco levemente à frente (para trabalhar mais o glúteo). Desça dobrando os dois joelhos até o joelho de trás quase tocar o chão.", "Empurre com o calcanhar da perna da frente para voltar à posição inicial.", "Repita alternando as pernas ou faça todas as repetições de um lado."], ["Joelho da frente passando muito da ponta do pé.", "Curvar as costas.", "Joelho entrando para dentro."]],
  "Panturrilha em pé": ["Panturrilha (gastrocnêmio e sóleo)", ["Fique em pé na ponta de um degrau (ou na máquina), com as pontas dos pés apoiadas e os calcanhares para fora. Os pés ficam na largura do quadril.", "Segure em um apoio para se equilibrar.", "Mantenha os joelhos esticados, sem travar."], ["Suba nas pontas dos pés o máximo que conseguir, apertando a panturrilha no alto.", "Segure um instante.", "Desça devagar, alongando bem a panturrilha, com os calcanhares abaixo do nível do degrau."], ["Fazer movimentos curtos.", "Dobrar os joelhos.", "Descer rápido, sem alongar."]],
  "Panturrilha sentado": ["Panturrilha (principalmente o sóleo)", ["Sente na máquina com as pontas dos pés na plataforma e as almofadas sobre os joelhos. Destrave o peso.", "Mantenha as costas retas.", "Comece com os calcanhares abaixo do nível da plataforma, alongando."], ["Suba nas pontas dos pés o máximo que conseguir, apertando a panturrilha.", "Segure um instante.", "Desça devagar até alongar bem."], ["Movimentos curtos.", "Descer rápido.", "Usar o impulso do corpo."]],
  "Panturrilha no leg press": ["Panturrilha", ["Sente na máquina de leg press com as costas apoiadas e apoie só as pontas dos pés na parte de baixo da plataforma. Estenda as pernas, sem travar os joelhos.", "Segure nas alças.", "Mantenha os joelhos esticados durante o exercício."], ["Empurre a plataforma com a ponta dos pés, esticando os tornozelos, apertando a panturrilha.", "Volte devagar, alongando a panturrilha, com os calcanhares abaixo da plataforma.", "Mantenha os joelhos quase esticados."], ["Travar os joelhos.", "Dobrar os joelhos.", "Movimentos curtos."]],
  "Panturrilha no smith": ["Panturrilha (gastrocnêmio e sóleo)", ["Apoie a barra do smith nos ombros e fique em pé na ponta de um degrau (ou anilha), com as pontas dos pés apoiadas e os calcanhares para fora.", "Destrave a barra e mantenha os joelhos esticados, sem travar.", "Mantenha as costas retas."], ["Suba nas pontas dos pés o máximo que conseguir, apertando a panturrilha.", "Segure um instante.", "Desça devagar, alongando bem, com os calcanhares abaixo do degrau. Trave a barra ao terminar."], ["Movimentos curtos.", "Dobrar os joelhos.", "Esquecer de travar a barra."]],
  "Panturrilha na máquina em pé": ["Panturrilha (gastrocnêmio e sóleo)", ["Posicione os ombros sob as almofadas e apoie as pontas dos pés na plataforma, com os calcanhares para fora. Destrave o peso.", "Mantenha os joelhos esticados, sem travar, e as costas retas.", "Mantenha o abdômen contraído."], ["Suba nas pontas dos pés o máximo possível, apertando a panturrilha.", "Segure um instante.", "Desça devagar, alongando bem."], ["Movimentos curtos.", "Dobrar os joelhos.", "Descer rápido."]],
  "Panturrilha burrinho": ["Panturrilha (gastrocnêmio)", ["Incline o corpo à frente, apoiando as mãos em um suporte, com o quadril sob a carga (ou com uma pessoa sentada sobre o quadril, ou a almofada da máquina). As pontas dos pés ficam em um degrau.", "Mantenha os joelhos esticados, sem travar.", "Mantenha as costas retas."], ["Suba nas pontas dos pés o máximo que conseguir, apertando a panturrilha.", "Segure um instante.", "Desça devagar, alongando bem."], ["Movimentos curtos.", "Dobrar os joelhos.", "Descer rápido."]],
  "Panturrilha unilateral em pé": ["Panturrilha (gastrocnêmio e sóleo)", ["Em pé na ponta de um degrau, apoie só um pé (a ponta do pé na borda). O outro pé fica levantado. Segure em um apoio para se equilibrar.", "Mantenha o joelho esticado, sem travar.", "Mantenha as costas retas."], ["Suba na ponta do pé o máximo que conseguir, apertando a panturrilha.", "Segure um instante.", "Desça devagar, alongando bem. Faça todas as repetições de um lado e depois troque."], ["Movimentos curtos.", "Perder o equilíbrio.", "Dobrar o joelho."]],
  "Panturrilha com halteres": ["Panturrilha (gastrocnêmio e sóleo)", ["Fique em pé na ponta de um degrau, com as pontas dos pés apoiadas. Segure um halter em cada mão ao lado do corpo.", "Mantenha os joelhos esticados, sem travar.", "Mantenha as costas retas."], ["Suba nas pontas dos pés o máximo que conseguir, apertando a panturrilha.", "Segure um instante.", "Desça devagar, alongando bem."], ["Movimentos curtos.", "Dobrar os joelhos.", "Balançar o corpo."]],
  "Panturrilha no hack": ["Panturrilha (gastrocnêmio e sóleo)", ["Posicione-se na máquina hack, com os ombros sob as almofadas e as costas apoiadas. Apoie só as pontas dos pés na parte de baixo da plataforma.", "Estenda as pernas, sem travar os joelhos.", "Mantenha o abdômen contraído."], ["Empurre a plataforma com a ponta dos pés, esticando os tornozelos, apertando a panturrilha.", "Volte devagar, alongando, com os calcanhares abaixo da plataforma.", "Mantenha os joelhos quase esticados."], ["Travar os joelhos.", "Dobrar os joelhos.", "Movimentos curtos."]],
  "Panturrilha no degrau": ["Panturrilha (gastrocnêmio e sóleo)", ["Fique em pé na ponta de um degrau, com as pontas dos pés apoiadas e os calcanhares para fora. Segure em um corrimão para se equilibrar.", "Mantenha os joelhos esticados, sem travar.", "Pode usar só o peso do corpo ou um halter."], ["Desça os calcanhares abaixo do nível do degrau, alongando a panturrilha.", "Suba o máximo que conseguir, apertando a panturrilha no alto.", "Faça o movimento devagar."], ["Movimentos curtos.", "Perder o equilíbrio.", "Dobrar os joelhos."]],
  "Abdominal reto": ["Abdômen (parte de cima do reto abdominal)", ["Deite de costas no chão, com os joelhos dobrados e os pés apoiados. Coloque as mãos ao lado da cabeça ou cruzadas no peito (sem puxar o pescoço).", "Mantenha o queixo afastado do peito, como se segurasse uma laranja.", "Contraia o abdômen."], ["Suba o tronco contraindo o abdômen, até as escápulas saírem do chão. Não é preciso subir até sentar.", "Segure um instante e desça devagar, sem relaxar completamente no chão.", "Solte o ar ao subir."], ["Puxar o pescoço com as mãos.", "Subir demais, com ajuda do quadril.", "Fazer rápido, com impulso."]],
  "Abdominal infra": ["Abdômen (parte de baixo)", ["Deite de costas no chão, com as pernas esticadas para cima (ou dobradas) e as mãos ao lado do corpo ou sob o quadril.", "Contraia o abdômen e mantenha a lombar apoiada no chão.", "Mantenha o pescoço relaxado."], ["Eleve o quadril em direção ao teto, usando o abdômen, sem balançar as pernas.", "Desça devagar, sem deixar a lombar sair do chão.", "Faça o movimento controlado."], ["Usar o impulso das pernas.", "Arquear a lombar.", "Descer rápido."]],
  "Abdominal na máquina": ["Abdômen (reto abdominal)", ["Sente na máquina e ajuste o assento. Segure as alças ou apoie o peito, conforme o aparelho.", "Mantenha os pés firmes e as costas apoiadas.", "Contraia o abdômen."], ["Puxe o tronco à frente, contraindo o abdômen, como se quisesse levar o peito em direção aos joelhos.", "Segure um instante e volte devagar, mantendo a tensão.", "Solte o ar ao contrair."], ["Puxar com os braços ou os quadris.", "Soltar o peso na volta.", "Usar carga alta demais."]],
  "Abdominal na polia": ["Abdômen (reto abdominal)", ["Ajoelhe-se de frente para a polia alta, segurando a corda perto da cabeça, com os cotovelos apontando para baixo. Os joelhos ficam afastados na largura do quadril.", "Mantenha o quadril parado e o tronco levemente inclinado à frente.", "Contraia o abdômen."], ["Curve o tronco para baixo, contraindo o abdômen, levando os cotovelos em direção aos joelhos.", "Segure um instante e volte devagar, mantendo a tensão.", "Não puxe com os braços. O movimento vem do abdômen."], ["Puxar com os braços.", "Mover o quadril.", "Usar carga alta demais."]],
  "Abdominal declinado": ["Abdômen (reto abdominal)", ["Deite no banco declinado, com os pés presos no apoio e os joelhos dobrados. Coloque as mãos ao lado da cabeça ou cruzadas no peito.", "Mantenha o queixo afastado do peito.", "Contraia o abdômen."], ["Suba o tronco contraindo o abdômen, até as escápulas saírem do banco.", "Desça devagar, sem relaxar completamente.", "Solte o ar ao subir."], ["Puxar o pescoço.", "Subir demais, sentando.", "Fazer rápido."]],
  "Abdominal canivete": ["Abdômen (reto abdominal) e flexores do quadril", ["Deite de costas no chão, com os braços esticados acima da cabeça e as pernas esticadas.", "Contraia o abdômen.", "Mantenha a lombar apoiada no chão."], ["Suba o tronco e as pernas ao mesmo tempo, tentando tocar os pés com as mãos, formando um V.", "Segure um instante e desça devagar.", "Solte o ar ao subir."], ["Usar o impulso dos braços.", "Curvar as costas demais.", "Pessoas com dor na lombar devem evitar."]],
  "Abdominal bicicleta": ["Abdômen (reto e oblíquos)", ["Deite de costas no chão, com as mãos atrás da cabeça (sem puxar o pescoço) e as pernas levantadas, com os joelhos dobrados.", "Contraia o abdômen e mantenha a lombar apoiada.", "Mantenha o queixo afastado do peito."], ["Leve o cotovelo direito ao joelho esquerdo, girando o tronco, enquanto estende a perna direita.", "Troque de lado, levando o cotovelo esquerdo ao joelho direito, em movimento de pedalar.", "Faça o movimento devagar e controlado."], ["Puxar o pescoço.", "Fazer rápido, sem contrair o abdômen.", "Arquear a lombar."]],
  "Abdominal oblíquo": ["Abdômen (oblíquos)", ["Deite de costas no chão, com os joelhos dobrados e os pés apoiados. Coloque as mãos atrás da cabeça, sem puxar o pescoço.", "Contraia o abdômen.", "Mantenha o queixo afastado do peito."], ["Suba o tronco girando e leve o cotovelo em direção ao joelho oposto.", "Desça devagar e alterne os lados.", "Solte o ar ao subir."], ["Puxar o pescoço.", "Fazer rápido.", "Subir demais, sentando."]],
  "Abdominal com roda": ["Abdômen, ombros e lombar", ["Ajoelhe-se em uma almofada, segurando a roda com as duas mãos, logo abaixo dos ombros.", "Contraia o abdômen e o glúteo, mantendo as costas retas.", "Comece com os braços esticados à frente."], ["Role a roda à frente devagar, mantendo o abdômen contraído, até onde conseguir sem curvar a lombar.", "Volte, puxando a roda com o abdômen, até a posição inicial.", "Comece com movimentos curtos e vá aumentando."], ["Curvar a lombar (risco de lesão).", "Ir longe demais, sem conseguir voltar.", "Usar os braços para voltar."]],
  "Prancha": ["Abdômen, lombar, ombros e glúteos", ["Apoie os antebraços no chão, com os cotovelos sob os ombros, e as pontas dos pés no chão.", "Mantenha o corpo reto, da cabeça aos calcanhares, como uma prancha, com o abdômen e o glúteo contraídos.", "Olhe para o chão, mantendo o pescoço alinhado com a coluna."], ["Segure a posição pelo tempo definido, respirando normalmente.", "Mantenha o quadril alinhado, sem deixar cair nem subir demais.", "Ao terminar, abaixe os joelhos ao chão."], ["Deixar o quadril cair (força a lombar).", "Subir demais o quadril.", "Prender a respiração."]],
  "Prancha lateral": ["Abdômen (oblíquos), lombar e ombros", ["Deite de lado, apoiando o antebraço no chão, com o cotovelo sob o ombro. Os pés ficam empilhados ou um à frente do outro.", "Mantenha o corpo reto, da cabeça aos pés.", "Contraia o abdômen."], ["Suba o quadril, deixando o corpo em linha reta, e segure a posição, respirando normalmente.", "Segure pelo tempo definido.", "Desça devagar e troque de lado."], ["Deixar o quadril cair.", "Girar o tronco.", "Prender a respiração."]],
  "Elevação de pernas": ["Abdômen (parte de baixo) e flexores do quadril", ["Deite de costas no chão, com as pernas esticadas e as mãos ao lado do corpo ou sob o quadril.", "Contraia o abdômen e mantenha a lombar apoiada no chão.", "Mantenha o pescoço relaxado."], ["Eleve as pernas retas até o quadril ficar a cerca de 90°, sem deixar a lombar sair do chão.", "Desça devagar, sem encostar os pés no chão.", "Solte o ar ao subir."], ["Arquear a lombar.", "Descer rápido.", "Usar o impulso."]],
  "Elevação de pernas na barra": ["Abdômen (parte de baixo), flexores do quadril e antebraço", ["Segure uma barra fixa e fique pendurado com os braços esticados. (Ou use o apoio de antebraços, a cadeira romana.)", "Mantenha o abdômen contraído e os ombros ativos.", "Comece com as pernas retas."], ["Eleve as pernas retas (ou dobradas, se for mais fácil) até a altura do quadril, ou mais.", "Desça devagar, sem balançar.", "Solte o ar ao subir."], ["Balançar o corpo.", "Usar o impulso.", "Descer rápido."]],
  "Russian twist": ["Abdômen (oblíquos e reto)", ["Sente no chão com os joelhos dobrados e o tronco inclinado para trás, cerca de 45°. Os pés ficam no chão ou levantados (mais difícil).", "Segure um peso (anilha, halter ou bola) com as duas mãos à frente do peito, se quiser.", "Mantenha as costas retas."], ["Gire o tronco para um lado, levando o peso ao lado do corpo, e depois para o outro lado.", "Mantenha o abdômen contraído e as costas retas.", "Faça o movimento controlado."], ["Curvar as costas.", "Girar só os braços.", "Fazer rápido, sem controle."]],
  "Lenhador na polia": ["Abdômen (oblíquos) e ombros", ["De lado para a polia, em pé, com os pés na largura dos ombros. Segure o cabo com as duas mãos.", "Mantenha os braços quase esticados e o abdômen contraído.", "Comece com o cabo no alto (ou embaixo)."], ["Gire o tronco, puxando o cabo em diagonal, de cima para baixo (ou de baixo para cima), mantendo os braços quase retos.", "Gire os pés e o quadril junto, sem forçar a lombar.", "Volte devagar e faça todas as repetições de um lado antes de trocar."], ["Girar só os braços.", "Forçar a lombar.", "Usar carga alta demais."]],
  "Mountain climber": ["Abdômen, ombros e quadril", ["Posicione-se na posição de flexão, com as mãos sob os ombros e o corpo reto, da cabeça aos calcanhares.", "Contraia o abdômen e o glúteo.", "Olhe para o chão."], ["Leve um joelho em direção ao peito, como se corresse, e troque rapidamente de perna.", "Mantenha o quadril baixo e o corpo reto.", "Respire de forma regular."], ["Levantar o quadril.", "Deixar a lombar cair.", "Fazer rápido, sem controle."]],
  "Dead bug": ["Abdômen (profundo) e estabilidade do tronco", ["Deite de costas no chão, com os braços esticados para o teto e os joelhos dobrados a 90°, acima do quadril.", "Pressione a lombar contra o chão e contraia o abdômen.", "Mantenha o pescoço relaxado."], ["Estenda o braço direito acima da cabeça e a perna esquerda esticada à frente, sem tirar a lombar do chão.", "Volte à posição inicial e troque, estendendo o braço esquerdo e a perna direita.", "Faça o movimento devagar, respirando normalmente."], ["Arquear a lombar.", "Fazer rápido.", "Prender a respiração."]]
};

const norm = (s) => String(s || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const MAPA = new Map(Object.entries(D).map(([n, v]) => [norm(n), { nome: n, musculos: v[0], preparo: v[1], execucao: v[2], erros: v[3] }]));

// Só devolve dica quando o nome é igual ao da biblioteca (para nunca mostrar a explicação de outro exercício).
export function dicaDoExercicio(nome) {
  const d = MAPA.get(norm(nome));
  return d ? { ...d, grupo: grupoDoExercicio(d.nome) } : null;
}
